        public void Initialize(Transform parent, Material worldMaterial, MaterialPropertyBlock colorBlock)
        {
            _parent = parent;
            _worldMaterial = worldMaterial;
            _colorBlock = colorBlock ?? new MaterialPropertyBlock();
            // Keep structural geometry depth writing. Making the shared material
            // transparent also changes rooms, floors and the outside city, so
            // distant quads can sort over the lobby and hide small lights.
            if (_worldMaterial != null && _coneMaterial == null)
            {
                _coneMaterial = new Material(_worldMaterial) { name = "Exterior Light Cones" };
                _coneMaterial.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                _coneMaterial.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                _coneMaterial.SetInt("_ZWrite", 0);
                _coneMaterial.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
                _coneMaterial.SetOverrideTag("RenderType", "Transparent");
            }

            if (_worldMaterial != null && _glazingMaterial == null)
            {
                _glazingMaterial = new Material(_worldMaterial) { name = "Exterior Facade Glazing" };
                _glazingMaterial.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                _glazingMaterial.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                _glazingMaterial.SetInt("_ZWrite", 0);
                _glazingMaterial.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
                _glazingMaterial.SetOverrideTag("RenderType", "Transparent");
            }

            Clear();
        }

        public void EnsureExteriorViews(TowerTopologyProjection topology, UndergroundDigProjection underground = null)
        {
            if (_parent == null || _worldMaterial == null) return;
            var floorCount = topology != null ? topology.FloorCount : TowerStructurePresenter.InitialFloorCount;
            if (floorCount <= 0) { Clear(); return; }

            CellBounds groundSlab = default;
            CellBounds topSlab = default;
            if (topology != null)
            {
                if (!topology.TryGetFloorSlab(0, out groundSlab)) groundSlab = new CellBounds(0, -14, 17);
                if (!topology.TryGetFloorSlab(floorCount - 1, out topSlab))
                    topSlab = new CellBounds(floorCount - 1, -14, 17);
            }
            else
            {
                groundSlab = new CellBounds(0, -14, 17);
                topSlab = new CellBounds(floorCount - 1, -14, 17);
            }

            _lightingTopology = topology;
            var slabsUnchanged = _renderedSlabs.Count == floorCount;
            for (var f = 0; slabsUnchanged && f < floorCount; f++)
            {
                var slab = topology != null && topology.TryGetFloorSlab(f, out var bounds)
                    ? bounds : new CellBounds(f, -14, 17);
                slabsUnchanged = _renderedSlabs.TryGetValue(f, out var previous) && previous.Equals(slab);
            }
            var geometryUnchanged = slabsUnchanged && _root != null && _renderedFloorCount == floorCount &&
                _renderedGroundSlab.Equals(groundSlab) && _renderedTopSlab.Equals(topSlab);
            if (geometryUnchanged)
            {
                if (underground == null || underground.Revision != _renderedUndergroundRevision)
                {
                    SyncExcavationViews(underground);
                    SyncUndergroundStructures(underground);
                    _renderedUndergroundRevision = underground?.Revision ?? -1;
                }
                return;
            }

            EnsureHierarchyRoots();
            RetireRemovedFloors(_leftFacadeRoot, floorCount);
            RetireRemovedFloors(_rightFacadeRoot, floorCount);
            RetireRemovedFloors(_volumetricLightRoot, floorCount);
            for (var i = _terracesRoot.childCount - 1; i >= 0; i--)
                RetireGeneratedChild(_terracesRoot.GetChild(i));
            PruneRetiredViews(_leftWallSlices, _rightWallSlices, _leftSpandrels, _rightSpandrels,
                _leftWindowFrames, _rightWindowFrames, _leftWindowGlasses, _rightWindowGlasses,
                _leftWindowSills, _rightWindowSills, _volumetricCones);
            _renderedSlabs.Clear();
            for (var f = 0; f < floorCount; f++)
                _renderedSlabs[f] = topology != null && topology.TryGetFloorSlab(f, out var bounds)
                    ? bounds : new CellBounds(f, -14, 17);
            _renderedFloorCount = floorCount;
            _renderedGroundSlab = groundSlab;
            _renderedTopSlab = topSlab;

            BuildFacades(topology, floorCount);
            BuildGroundDressing(groundSlab);
            SyncExcavationViews(underground);
            SyncUndergroundStructures(underground);
            _renderedUndergroundRevision = underground?.Revision ?? -1;
            EnsureExteriorWindows(topology, floorCount);
            BuildRoofline(topology, floorCount, topSlab);
            BuildSetbackTerraces(topology, floorCount);
            BuildFrontFacadeEnvelope(topology, floorCount);
            CalculateStageBounds(floorCount, groundSlab, topSlab);
        }

        private void RetireRemovedFloors(Transform parent, int floorCount)
        {
            for (var i = parent.childCount - 1; i >= 0; i--)
            {
                var child = parent.GetChild(i);
                var separator = child.name.LastIndexOf(' ');
                if (separator < 0 || !int.TryParse(child.name.Substring(separator + 1), out var floor) || floor < floorCount)
                    continue;
                var filter = child.GetComponent<MeshFilter>();
                if (filter != null && _coneMeshes.Remove(filter.sharedMesh))
                {
                    var mesh = filter.sharedMesh;
                    DestroyGeneratedMesh(ref mesh);
                }
                RetireGeneratedChild(child);
            }
            if (floorCount <= 1)
            {
                var downspout = parent.Find("Left Downspout") ?? parent.Find("Right Downspout");
                if (downspout != null) RetireGeneratedChild(downspout);
            }
        }

        private static void RetireGeneratedChild(Transform child)
        {
            child.gameObject.SetActive(false);
            child.SetParent(null, false);
            DestroyGenerated(child.gameObject);
        }

        private static void PruneRetiredViews(params List<GameObject>[] lists)
        {
            foreach (var list in lists)
                list.RemoveAll(view => view == null || view.transform.parent == null);
        }

        private void EnsureHierarchyRoots()
        {
            if (_root != null) return;

            var existing = _parent.Find("Building Exterior Envelope");
            if (existing != null)
            {
                _root = existing;
            }
            else
            {
                _root = new GameObject("Building Exterior Envelope").transform;
                _root.SetParent(_parent, false);
            }

            _leftFacadeRoot = EnsureChildTransform(_root, "Left Facade");
            _rightFacadeRoot = EnsureChildTransform(_root, "Right Facade");
            _rooflineRoot = EnsureChildTransform(_root, "Roofline & Capping");
            _fixturesRoot = EnsureChildTransform(_rooflineRoot, "Rooftop Fixtures");
            _terracesRoot = EnsureChildTransform(_root, "Setback Terraces");
            _volumetricLightRoot = EnsureChildTransform(_root, "Exterior Volumetric Lighting");
            _groundRoot = EnsureChildTransform(_root, "Ground Dressing");
            _frontFacadeRoot = EnsureChildTransform(_root, "Front Facade Envelope");
        }

        private static Transform EnsureChildTransform(Transform parent, string name)
        {
            var child = parent.Find(name);
            if (child != null) return child;
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            return go.transform;
        }

        private void BuildFacades(TowerTopologyProjection topology, int floorCount)
        {
            // 1. Foundation Plinth (Left side)
            var ground = topology != null && topology.TryGetFloorSlab(0, out var g) ? g : new CellBounds(0, -14, 16);
            var groundLeft = -2.4f + ground.MinX * 0.5f;
            var groundBaseline = TowerStructurePresenter.FloorY(0) - 0.74f;

            UpdateOrCreateQuad(_leftFacadeRoot, "Left Foundation Plinth", PlinthColor,
                new Vector3(groundLeft - WallThickness * 0.5f - 0.04f, groundBaseline - 0.24f, 0.10f),
                new Vector2(WallThickness + 0.08f, 0.48f));

            // Anchor the upper downspout to the upper facade. The ground slab can
            // expand independently, and must not pull a vertical line through the
            // open setback beside the tower.
            var topFloorY = TowerStructurePresenter.FloorY(floorCount - 1) + 1.01f;
            if (floorCount > 1)
            {
                var firstUpper = topology != null && topology.TryGetFloorSlab(1, out var upper)
                    ? upper : new CellBounds(1, -14, 16);
                var upperLeft = -2.4f + firstUpper.MinX * 0.5f;
                var downspoutBottom = TowerStructurePresenter.FloorY(1) - 0.74f;
                UpdateOrCreateQuad(_leftFacadeRoot, "Left Downspout", DownspoutColor,
                    new Vector3(upperLeft - WallThickness - 0.02f, (downspoutBottom + topFloorY) * 0.5f, -0.05f),
                    new Vector2(0.04f, topFloorY - downspoutBottom));
            }

            // Per-Floor Left Wall Slices & Spandrels
            for (var f = 0; f < floorCount; f++)
            {
                var slab = topology != null && topology.TryGetFloorSlab(f, out var s) ? s : new CellBounds(f, -14, 16);
                var worldLeft = -2.4f + slab.MinX * 0.5f;
                var floorY = TowerStructurePresenter.FloorY(f);
                var baselineY = floorY - 0.74f;

                // Wall Section
                var wallObj = UpdateOrCreateQuad(_leftFacadeRoot, $"Left Wall {f}", WallCoreColor,
                    new Vector3(worldLeft - WallThickness * 0.5f, floorY, 0.10f),
                    new Vector2(WallThickness, 1.75f));
                if (!_leftWallSlices.Contains(wallObj)) _leftWallSlices.Add(wallObj);

                // Outer Weather Trim
                UpdateOrCreateQuad(_leftFacadeRoot, $"Left Cladding {f}", CladdingColor,
                    new Vector3(worldLeft - WallThickness + CladdingThickness * 0.5f, floorY, -0.04f),
                    new Vector2(CladdingThickness, 1.75f));

                // Horizontal Spandrel Plate
                var spandrelObj = UpdateOrCreateQuad(_leftFacadeRoot, $"Left Spandrel {f}", SpandrelColor,
                    new Vector3(worldLeft - (WallThickness + SpandrelProtrusion) * 0.5f, baselineY, 0.08f),
                    new Vector2(WallThickness + SpandrelProtrusion, 0.18f));
                if (!_leftSpandrels.Contains(spandrelObj)) _leftSpandrels.Add(spandrelObj);
            }

            // Right Facade
            // Floor 0 Lobby Entrance Threshold & Cantilever Awning
            var groundRight = -2.4f + (ground.MaxX + 1) * 0.5f;
            UpdateOrCreateQuad(_rightFacadeRoot, "Lobby Entrance Portal Frame", CladdingColor,
                new Vector3(groundRight - 0.05f, TowerStructurePresenter.FloorY(0), 0.10f),
                new Vector2(0.10f, 1.55f));

            UpdateOrCreateQuad(_rightFacadeRoot, "Lobby Cantilever Canopy", CanopyColor,
                new Vector3(groundRight + 0.65f, groundBaseline + 1.28f, 0.38f),
                new Vector2(1.40f, 0.14f));

            // A framed, lit street entrance stays outside the walkable lobby.
            var entranceX = groundRight + 0.42f;
            var floorY0 = TowerStructurePresenter.FloorY(0);
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Glass", new Color(0.16f, 0.32f, 0.39f),
                new Vector3(entranceX, floorY0 - 0.12f, 0.17f), new Vector2(0.70f, 1.12f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Left Jamb", CorniceTrimColor,
                new Vector3(entranceX - 0.39f, floorY0 - 0.08f, 0.04f), new Vector2(0.07f, 1.32f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Right Jamb", CorniceTrimColor,
                new Vector3(entranceX + 0.39f, floorY0 - 0.08f, 0.04f), new Vector2(0.07f, 1.32f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Lintel", CorniceTrimColor,
                new Vector3(entranceX, floorY0 + 0.61f, 0.02f), new Vector2(0.86f, 0.10f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Door Seam", new Color(0.54f, 0.72f, 0.70f),
                new Vector3(entranceX, floorY0 - 0.13f, -0.02f), new Vector2(0.025f, 1.08f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Light", new Color(1f, 0.76f, 0.38f),
                new Vector3(entranceX, floorY0 + 0.77f, -0.06f), new Vector2(0.24f, 0.055f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Sign Panel", new Color(0.10f, 0.25f, 0.27f),
                new Vector3(entranceX, floorY0 + 0.87f, 0.08f), new Vector2(1.05f, 0.22f));
            UpdateOrCreateQuad(_rightFacadeRoot, "Entrance Sign Mark", new Color(0.48f, 0.91f, 0.68f),
                new Vector3(entranceX, floorY0 + 0.87f, -0.02f), new Vector2(0.42f, 0.045f));

            // Upper Floor Right Wall Slices
            for (var f = 1; f < floorCount; f++)
            {
                var slab = topology != null && topology.TryGetFloorSlab(f, out var s) ? s : new CellBounds(f, -14, 16);
                var worldRight = -2.4f + (slab.MaxX + 1) * 0.5f;
                var floorY = TowerStructurePresenter.FloorY(f);
                var baselineY = floorY - 0.74f;

                var wallObj = UpdateOrCreateQuad(_rightFacadeRoot, $"Right Wall {f}", WallCoreColor,
                    new Vector3(worldRight + WallThickness * 0.5f, floorY, 0.10f),
                    new Vector2(WallThickness, 1.75f));
                if (!_rightWallSlices.Contains(wallObj)) _rightWallSlices.Add(wallObj);

                UpdateOrCreateQuad(_rightFacadeRoot, $"Right Cladding {f}", CladdingColor,
                    new Vector3(worldRight + WallThickness - CladdingThickness * 0.5f, floorY, -0.04f),
                    new Vector2(CladdingThickness, 1.75f));

                var spandrelObj = UpdateOrCreateQuad(_rightFacadeRoot, $"Right Spandrel {f}", SpandrelColor,
                    new Vector3(worldRight + (WallThickness + SpandrelProtrusion) * 0.5f, baselineY, 0.08f),
                    new Vector2(WallThickness + SpandrelProtrusion, 0.18f));
                if (!_rightSpandrels.Contains(spandrelObj)) _rightSpandrels.Add(spandrelObj);
            }

            // Downspout Right (from Floor 1 to Ground Canopy)
            if (floorCount > 1)
            {
                var f1Slab = topology != null && topology.TryGetFloorSlab(1, out var s1) ? s1 : new CellBounds(1, -14, 16);
                var f1Right = -2.4f + (f1Slab.MaxX + 1) * 0.5f;
                var downHeightR = topFloorY - (TowerStructurePresenter.FloorY(1) - 0.74f);
                var downCenterR = ((TowerStructurePresenter.FloorY(1) - 0.74f) + topFloorY) * 0.5f;
                UpdateOrCreateQuad(_rightFacadeRoot, "Right Downspout", DownspoutColor,
                    new Vector3(f1Right + WallThickness + 0.02f, downCenterR, -0.05f),
                    new Vector2(0.04f, downHeightR));
            }
        }

        private void BuildGroundDressing(CellBounds ground)
        {
            var left = -2.4f + ground.MinX * 0.5f;
            var right = -2.4f + (ground.MaxX + 1) * 0.5f;
            var baseline = TowerStructurePresenter.FloorY(0) - 0.74f;
            var width = right - left;
            var center = (left + right) * 0.5f;
            // Author subterranean geometry in logical cells, then map it onto the Tower's columns/storeys.
            _undercityRoot = EnsureChildTransform(_groundRoot, "Undercity");
            var cellWidth = GridPlacementController.UndergroundCellWidth;
            var cellHeight = GridPlacementController.UndergroundCellHeight;
            _undercityRoot.localScale = new Vector3(cellWidth, cellHeight, 1f);
            _undercityRoot.localPosition = new Vector3(center * (1f - cellWidth), baseline * (1f - cellHeight), 0f);
            var earthWidth = UndergroundDigState.GridWidthCells * GridPlacementController.UndergroundCellSize;
            var earthLeft = center - earthWidth * 0.5f;
            var earthDepth = UndergroundDigState.MaxDepthCells * GridPlacementController.UndergroundCellSize;

            UpdateOrCreateQuad(_undercityRoot, "Foundation Soil", new Color(0.25f, 0.16f, 0.10f),
                new Vector3(center, baseline - earthDepth * 0.5f, 0.48f), new Vector2(earthWidth, earthDepth));
            // Dense continuous samples give soil grain and fractured stone instead
            // of colored stripes. All geology remains a single static draw batch.
            var geology = new FacadeMeshBuilder();
            const int rows = 96;
            const int columns = 256;
            // Shared lattice nodes avoid duplicating the dense soil surface per quad.
            for (var row = 0; row <= rows; row++)
            for (var column = 0; column <= columns; column++)
            {
                var x = earthLeft + earthWidth * column / columns;
                var depth = earthDepth * row / rows;
                geology.Vertices.Add(new Vector3(x, baseline - depth, EarthTileZ));
                geology.Colors.Add(EarthColor(x, depth));
                geology.UVs.Add(new Vector2(column / (float)columns, row / (float)rows));
            }
            for (var row = 0; row < rows; row++)
            for (var column = 0; column < columns; column++)
            {
                var topLeft = row * (columns + 1) + column;
                var bottomLeft = topLeft + columns + 1;
                geology.Triangles.Add(topLeft);
                geology.Triangles.Add(topLeft + 1);
                geology.Triangles.Add(bottomLeft + 1);
                geology.Triangles.Add(topLeft);
                geology.Triangles.Add(bottomLeft + 1);
                geology.Triangles.Add(bottomLeft);
            }
            // Angular stone fragments vary in size, shape and burial depth.
            for (var i = 0; i < 1800; i++)
            {
                var x = earthLeft + 0.2f + (earthWidth - 0.4f) * EarthRandom(i, 7);
                var d = 0.2f + (earthDepth - 0.4f) * EarthRandom(i, 13);
                var y = baseline - d;
                var size = Mathf.Lerp(0.025f, 0.17f, Mathf.Pow(EarthRandom(i, 19), 3f));
                var color = EarthColor(x, d) * Mathf.Lerp(0.55f, 1.35f, EarthRandom(i, 23));
                color.a = 1f;
                var first = geology.AddQuad(x - size, x + size, y - size * 0.42f,
                    y + size * 0.42f, EarthDetailZ, color);
                geology.Vertices[first] += new Vector3(size * 0.5f, 0f, 0f);
                geology.Vertices[first + 1] += new Vector3(-size * 0.2f, size * 0.19f, 0f);
                geology.Vertices[first + 2] += new Vector3(-size * 0.6f, 0f, 0f);
                geology.Vertices[first + 3] += new Vector3(size * 0.2f, -size * 0.13f, 0f);
            }
            // Discontinuous fractures are concentrated in deeper rock, not a grid.
            for (var i = 0; i < 100; i++)
            {
                var x = earthLeft + 1.5f + (earthWidth - 3f) * EarthRandom(i, 31);
                var y = baseline - 2f - (earthDepth - 3f) * EarthRandom(i, 37);
                var length = 0.14f + EarthRandom(i, 41) * 0.65f;
                for (var part = 0; part < 4; part++)
                {
                    var nextX = x + (EarthRandom(i * 4 + part, 43) - 0.5f) * length;
                    var nextY = y - length * 0.25f;
                    AddEarthLine(geology, new Vector2(x, y), new Vector2(nextX, nextY),
                        0.007f, EarthDetailZ - 0.001f, new Color(0.025f, 0.024f, 0.022f));
                    x = nextX;
                    y = nextY;
                }
            }
            ReplaceGroundMesh("Continuous Earth Strata", geology);
            UpdateOrCreateQuad(_groundRoot, "Foundation Stone", new Color(0.18f, 0.27f, 0.23f),
                new Vector3(center, baseline - 0.10f, 0.46f), new Vector2(width, 0.17f));
            UpdateOrCreateQuad(_groundRoot, "Ground Green Edge", new Color(0.16f, 0.36f, 0.27f),
                new Vector3(center, baseline + 0.012f, 0.02f), new Vector2(width, 0.035f));
            for (var i = 0; i < 5; i++)
            {
                var x = left + 0.55f + i * Mathf.Max(0.25f, (width - 1.1f) / 4f);
                UpdateOrCreateQuad(_groundRoot, $"Foundation Pier {i}", new Color(0.21f, 0.31f, 0.27f),
                    new Vector3(x, baseline - 0.36f, 0.46f), new Vector2(0.12f, 0.55f));
            }

            // These quiet wall bays sit in front of the slab (z=1) but behind
            // actual room backdrops (z=0.7), so new rooms naturally cover them.
            const float shaftLeft = -2.4f;
            var westSpan = shaftLeft - left;
            if (westSpan > 2f)
            {
                var baySpacing = westSpan / 6f;
                for (var i = 1; i <= 5; i++)
                {
                    var bayX = left + baySpacing * i;
                    UpdateOrCreateQuad(_groundRoot, $"West Bay Mullion {i}", new Color(0.12f, 0.27f, 0.25f),
                        new Vector3(bayX, TowerStructurePresenter.FloorY(0), 0.91f), new Vector2(0.035f, 1.16f));
                    UpdateOrCreateQuad(_groundRoot, $"West Bay Marker {i}", new Color(0.40f, 0.52f, 0.39f),
                        new Vector3(bayX - baySpacing * 0.5f, TowerStructurePresenter.FloorY(0) + 0.56f, 0.90f),
                        new Vector2(0.10f, 0.035f));
                }
            }

            var apronX = right + 1.05f;
            UpdateOrCreateQuad(_groundRoot, "Entrance Paving", new Color(0.32f, 0.42f, 0.40f),
                new Vector3(apronX, baseline - 0.03f, 0.13f), new Vector2(2.1f, 0.11f));
            UpdateOrCreateQuad(_groundRoot, "Entrance Step Highlight", new Color(0.55f, 0.70f, 0.62f),
                new Vector3(right + 0.43f, baseline + 0.04f, 0.01f), new Vector2(0.86f, 0.045f));
            UpdateOrCreateQuad(_groundRoot, "Entrance Planter", new Color(0.21f, 0.37f, 0.30f),
                new Vector3(right + 1.70f, baseline + 0.18f, 0.02f), new Vector2(0.42f, 0.28f));
            UpdateOrCreateQuad(_groundRoot, "Entrance Greenery", new Color(0.39f, 0.68f, 0.40f),
                new Vector3(right + 1.70f, baseline + 0.43f, -0.01f), new Vector2(0.30f, 0.32f));
        }

        private static float EarthRandom(int index, int salt)
        {
            unchecked
            {
                var value = (uint)(index * 747796405 + salt * 289133645);
                value = ((value >> (int)((value >> 28) + 4)) ^ value) * 277803737u;
                value = (value >> 22) ^ value;
                return (value & 0x00ffffff) / 16777215f;
            }
        }

        private static Color EarthColor(float x, float depth)
        {
            var warpedDepth = depth + (Mathf.PerlinNoise(x * 0.19f + 71f, depth * 0.12f + 19f) - 0.5f) * 1.1f;
            var rock = Mathf.SmoothStep(0f, 1f, (warpedDepth - 2.1f) / 6.4f);
            var color = Color.Lerp(new Color(0.092f, 0.071f, 0.048f), new Color(0.061f, 0.065f, 0.066f), rock);
            var broad = Mathf.PerlinNoise(x * 0.49f + 11f, depth * 1.2f + 23f);
            var grain = Mathf.PerlinNoise(x * 12.7f + 39f, depth * 14.3f + 53f);
            var medium = Mathf.PerlinNoise(x * 3.1f + 7f, depth * 4.7f + 17f);
            // Uneven sediment horizons have restrained contrast and independent widths.
            var horizon = Mathf.Sin(warpedDepth * 2.7f + Mathf.Sin(warpedDepth * 1.21f) * 2f);
            color *= 0.66f + broad * 0.36f + medium * 0.25f + grain * 0.22f + horizon * 0.04f;
            color.a = 1f;
            return color;
        }

        private static void AddEarthLine(FacadeMeshBuilder builder, Vector2 start, Vector2 end,
            float width, float z, Color color)
        {
            var normal = new Vector2(-(end - start).y, (end - start).x).normalized * width;
            var first = builder.AddQuad(0f, 0f, 0f, 0f, z, color);
            builder.Vertices[first] = new Vector3(start.x - normal.x, start.y - normal.y, z);
            builder.Vertices[first + 1] = new Vector3(end.x - normal.x, end.y - normal.y, z);
            builder.Vertices[first + 2] = new Vector3(end.x + normal.x, end.y + normal.y, z);
            builder.Vertices[first + 3] = new Vector3(start.x + normal.x, start.y + normal.y, z);
        }

        private static void AddExcavationRim(FacadeMeshBuilder builder, Vector2 start,
            Vector2 end, Vector2 inward, int seed)
        {
            const int pieces = 10;
            for (var part = 0; part < pieces; part++)
            {
                var a = Vector2.Lerp(start, end, part / (float)pieces);
                var b = Vector2.Lerp(start, end, (part + 1f) / pieces);
                var thicknessA = 0.028f + EarthRandom(seed + part, 59) * 0.052f;
                var thicknessB = 0.028f + EarthRandom(seed + part + 1, 59) * 0.052f;
                var rock = new Color(0.091f, 0.081f, 0.064f) * (0.68f + EarthRandom(seed + part, 61) * 0.45f);
                rock.a = 1f;
                var first = builder.AddQuad(0f, 0f, 0f, 0f, 0.35f, rock);
                var innerA = a + inward * thicknessA;
                var innerB = b + inward * thicknessB;
                builder.Vertices[first] = new Vector3(a.x, a.y, 0.35f);
                builder.Vertices[first + 1] = new Vector3(b.x, b.y, 0.35f);
                builder.Vertices[first + 2] = new Vector3(innerB.x, innerB.y, 0.35f);
                builder.Vertices[first + 3] = new Vector3(innerA.x, innerA.y, 0.35f);
                // Broken inner rock catches light; the cavity-facing lip falls into shadow.
                AddEarthLine(builder, innerA, innerB, 0.009f, 0.349f, new Color(0.014f, 0.016f, 0.018f));
            }
        }

        private void ReplaceGroundMesh(string name, FacadeMeshBuilder builder)
        {
            var previous = _undercityRoot.Find(name);
            if (previous != null)
            {
                var oldMesh = previous.GetComponent<MeshFilter>().sharedMesh;
                _coneMeshes.Remove(oldMesh);
                DestroyGeneratedMesh(ref oldMesh);
            }
            var mesh = builder.BuildMesh(name);
            _coneMeshes.Add(mesh); // Existing generated-mesh lifetime owner clears these on teardown.
            var view = EnsureChildWithMesh(_undercityRoot, name, mesh, _worldMaterial);
            SetColor(view.GetComponent<MeshRenderer>(), Color.white);
        }

        private void SyncExcavationViews(UndergroundDigProjection underground)
        {
            var active = new HashSet<UndergroundCell>();
            var floored = new HashSet<UndergroundCell>();
            if (underground != null)
            {
                for (var i = 0; i < underground.ExcavatedCells.Count; i++)
                    active.Add(underground.ExcavatedCells[i]);
                for (var i = 0; i < underground.FlooredCells.Count; i++)
                    floored.Add(underground.FlooredCells[i]);
            }

            var retired = new List<UndergroundCell>();
            foreach (var pair in _excavationViews)
            {
                if (!active.Contains(pair.Key))
                {
                    if (pair.Value != null)
                    {
                        if (UnityEngine.Application.isPlaying) Object.Destroy(pair.Value);
                        else Object.DestroyImmediate(pair.Value);
                    }
                    retired.Add(pair.Key);
                }
            }
            for (var i = 0; i < retired.Count; i++) _excavationViews.Remove(retired[i]);

            retired.Clear();
            foreach (var pair in _lairFloorViews)
            {
                if (!floored.Contains(pair.Key))
                {
                    if (pair.Value != null)
                    {
                        if (UnityEngine.Application.isPlaying) Object.Destroy(pair.Value);
                        else Object.DestroyImmediate(pair.Value);
                    }
                    retired.Add(pair.Key);
                }
            }
            for (var i = 0; i < retired.Count; i++) _lairFloorViews.Remove(retired[i]);

            if (underground == null)
            {
                ReplaceGroundMesh("Excavation Rock Faces", new FacadeMeshBuilder());
                return;
            }
            var baseline = TowerStructurePresenter.FloorY(0) - 0.74f;
            var groundCenter = -2.4f + (_renderedGroundSlab.MinX + _renderedGroundSlab.MaxX + 1) * 0.25f;
            if (_renderedGroundSlab.Width <= 0) groundCenter = -1.4f;
            var earthLeft = groundCenter - UndergroundDigState.GridWidthCells * GridPlacementController.UndergroundCellSize * 0.5f;
            var faces = new FacadeMeshBuilder();
            for (var i = 0; i < underground.ExcavatedCells.Count; i++)
            {
                var cell = underground.ExcavatedCells[i];
                var x = earthLeft + (cell.X + 0.5f) * GridPlacementController.UndergroundCellSize;
                var y = baseline - (cell.Depth + 0.5f) * GridPlacementController.UndergroundCellSize;
                var view = UpdateOrCreateQuad(_undercityRoot, $"Excavated Cell {cell.X}_{cell.Depth}",
                    new Color(0.004f, 0.007f, 0.009f), new Vector3(x, y, ExcavationZ), new Vector2(1.005f, 1.005f));
                _excavationViews[cell] = view;
                // Only the exposed perimeter receives rock and cavity shading.
                var left = x - 0.5f;
                var right = x + 0.5f;
                var bottom = y - 0.5f;
                var top = y + 0.5f;
                var seed = cell.X * 107 + cell.Depth * 997;
                if (!active.Contains(new UndergroundCell(cell.X - 1, cell.Depth)))
                    AddExcavationRim(faces, new Vector2(left, bottom), new Vector2(left, top), Vector2.right, seed);
                if (!active.Contains(new UndergroundCell(cell.X + 1, cell.Depth)))
                    AddExcavationRim(faces, new Vector2(right, bottom), new Vector2(right, top), Vector2.left, seed + 11);
                if (!active.Contains(new UndergroundCell(cell.X, cell.Depth - 1)))
                    AddExcavationRim(faces, new Vector2(left, top), new Vector2(right, top), Vector2.down, seed + 23);
                if (!active.Contains(new UndergroundCell(cell.X, cell.Depth + 1)))
                    AddExcavationRim(faces, new Vector2(left, bottom), new Vector2(right, bottom), Vector2.up, seed + 37);

            }

            ReplaceGroundMesh("Excavation Rock Faces", faces);

            for (var i = 0; i < underground.FlooredCells.Count; i++)
            {
                var cell = underground.FlooredCells[i];
                var x = earthLeft + (cell.X + 0.5f) * GridPlacementController.UndergroundCellSize;
                var y = baseline - (cell.Depth + 0.5f) * GridPlacementController.UndergroundCellSize;
                var floor = UpdateOrCreateQuad(_undercityRoot, $"Lair Floor {cell.X}_{cell.Depth}",
                    new Color(0.11f, 0.19f, 0.22f), new Vector3(x, y, LairFloorZ), new Vector2(1.005f, 1.005f));
                UpdateOrCreateQuad(floor.transform, "Floor Slab", new Color(0.25f, 0.40f, 0.42f),
                    new Vector3(0f, -0.43f, -0.02f), new Vector2(1.005f, 0.16f));
                UpdateOrCreateQuad(floor.transform, "Floor Edge Light", new Color(0.48f, 0.79f, 0.70f),
                    new Vector3(0f, -0.34f, -0.03f), new Vector2(1.005f, 0.025f));
                _lairFloorViews[cell] = floor;
            }
        }

        private void SyncUndergroundStructures(UndergroundDigProjection underground)
        {
            var corridors = new HashSet<UndergroundCell>();
            var shaft = new HashSet<UndergroundCell>();
            var rooms = new HashSet<int>();
            if (underground != null)
            {
                for (var i = 0; i < underground.Corridors.Count; i++) corridors.Add(underground.Corridors[i]);
                for (var i = 0; i < underground.ServiceShaftCells.Count; i++) shaft.Add(underground.ServiceShaftCells[i]);
                for (var i = 0; i < underground.Rooms.Count; i++) rooms.Add(underground.Rooms[i].Id);
            }
            RetireMissingCellViews(_corridorViews, corridors);
            RetireMissingCellViews(_shaftViews, shaft);
            var retiredRooms = new List<int>();
            foreach (var pair in _undergroundRoomViews)
                if (!rooms.Contains(pair.Key))
                {
                    if (pair.Value != null) RetireUndercityDetailGroup(pair.Value.transform);
                    retiredRooms.Add(pair.Key);
                }
            for (var i = 0; i < retiredRooms.Count; i++) _undergroundRoomViews.Remove(retiredRooms[i]);
            if (underground == null) { DestroyGenerated(_accessCoreView); _accessCoreView = null; return; }

            var baseline = TowerStructurePresenter.FloorY(0) - 0.74f;
            var groundCenter = -2.4f + (_renderedGroundSlab.MinX + _renderedGroundSlab.MaxX + 1) * 0.25f;
            if (_renderedGroundSlab.Width <= 0) groundCenter = -1.4f;
            var earthLeft = groundCenter - UndergroundDigState.GridWidthCells * GridPlacementController.UndergroundCellSize * 0.5f;

            foreach (var cell in corridors)
            {
                var x = earthLeft + cell.X + 0.5f;
                var y = baseline - cell.Depth - 0.5f;
                var view = UpdateOrCreateQuad(_undercityRoot, $"Underground Corridor {cell.X}_{cell.Depth}",
                    new Color(0.12f, 0.18f, 0.21f), new Vector3(x, y, 0.30f), new Vector2(1.005f, 1.005f));
                UpdateOrCreateQuad(view.transform, "Walkway", new Color(0.38f, 0.41f, 0.40f),
                    new Vector3(0f, -0.38f, -0.015f), new Vector2(1.005f, 0.12f));
                UpdateOrCreateQuad(view.transform, "Wayfinding", new Color(0.65f, 0.79f, 0.58f),
                    new Vector3(0f, -0.25f, -0.02f), new Vector2(0.30f, 0.025f));
                UpdateOrCreateQuad(view.transform, "Concrete Ceiling", new Color(0.30f, 0.34f, 0.35f),
                    new Vector3(0f, 0.43f, -0.02f), new Vector2(1.005f, 0.10f));
                // Overhead brackets support the ceiling without slicing the walkable tunnel into boxes.
                var rib = UpdateOrCreateQuad(view.transform, "Steel Rib", new Color(0.43f, 0.49f, 0.50f),
                    new Vector3(-0.40f, 0.32f, -0.03f), new Vector2(0.06f, 0.18f));
                rib.SetActive(cell.X % 2 == 0);
                UpdateOrCreateQuad(view.transform, "Wall Panel Joint", new Color(0.09f, 0.13f, 0.15f),
                    new Vector3(0f, 0.08f, -0.01f), new Vector2(1f, 0.012f));
                var recess = UpdateOrCreateQuad(view.transform, "Light Recess", new Color(0.06f, 0.09f, 0.10f),
                    new Vector3(0.05f, 0.32f, -0.032f), new Vector2(0.32f, 0.08f));
                recess.SetActive(cell.X % 2 == 0);
                var lamp = UpdateOrCreateQuad(view.transform, "Work Light", new Color(0.92f, 0.75f, 0.41f),
                    new Vector3(0.05f, 0.30f, -0.035f), new Vector2(0.23f, 0.045f));
                lamp.SetActive(cell.X % 2 == 0);
                var wash = new FacadeMeshBuilder();
                AddUndercityLightWash(wash, 0.05f, 0.29f, 0.02f, 0.15f, 0.30f, -0.018f);
                ReplaceUndercityDetailMesh(view.transform, "Light Wall Wash", wash, _coneMaterial);
                view.transform.Find("Light Wall Wash").gameObject.SetActive(cell.X % 2 == 0);
                _corridorViews[cell] = view;
            }

            foreach (var cell in shaft)
            {
                var x = earthLeft + cell.X + 0.5f;
                var y = baseline - cell.Depth - 0.5f;
                var view = UpdateOrCreateQuad(_undercityRoot, $"Underground Shaft {cell.X}_{cell.Depth}",
                    new Color(0.08f, 0.16f, 0.20f), new Vector3(x, y, 0.26f), new Vector2(1.005f, 1.005f));
                UpdateOrCreateQuad(view.transform, "Left Rail", new Color(0.50f, 0.67f, 0.65f),
                    new Vector3(-0.27f, 0f, -0.02f), new Vector2(0.05f, 1.005f));
                UpdateOrCreateQuad(view.transform, "Right Rail", new Color(0.50f, 0.67f, 0.65f),
                    new Vector3(0.27f, 0f, -0.02f), new Vector2(0.05f, 1.005f));
                for (var rung = 0; rung < 3; rung++)
                    UpdateOrCreateQuad(view.transform, $"Rung {rung}", new Color(0.42f, 0.60f, 0.58f),
                        new Vector3(0f, -0.30f + rung * 0.30f, -0.025f), new Vector2(0.56f, 0.045f));
                _shaftViews[cell] = view;
            }

            if (underground.AccessCore.HasValue)
            {
                var cell = underground.AccessCore.Value;
                _accessCoreView = UpdateOrCreateQuad(_undercityRoot, "Underground Access Core",
                    new Color(0.85f, 0.65f, 0.30f),
                    new Vector3(earthLeft + cell.X + 0.5f, baseline - cell.Depth - 0.5f, 0.23f),
                    new Vector2(0.78f, 0.09f));
            }
            else { DestroyGenerated(_accessCoreView); _accessCoreView = null; }

            for (var i = 0; i < underground.Rooms.Count; i++)
            {
                var room = underground.Rooms[i];
                var x = earthLeft + room.X + room.Width * 0.5f;
                var y = baseline - room.Depth - room.Height * 0.5f;
                var root = _undercityRoot.Find($"Underground Room {room.Id}");
                if (root == null)
                {
                    root = new GameObject($"Underground Room {room.Id}").transform;
                    root.SetParent(_undercityRoot, false);
                }
                root.localPosition = new Vector3(x, y, 0f);
                var color = UndergroundRoomColor(room.Type);
                UpdateOrCreateQuad(root, "Room Backdrop", color, new Vector3(0f, 0f, 0.29f),
                    new Vector2(room.Width - 0.04f, room.Height - 0.04f));
                UpdateOrCreateQuad(root, "Room Header", new Color(0.08f, 0.15f, 0.19f),
                    new Vector3(0f, room.Height * 0.5f - 0.27f, 0.25f), new Vector2(room.Width - 0.18f, 0.50f));
                UpdateOrCreateQuad(root, "Room Floor", new Color(0.42f, 0.53f, 0.52f),
                    new Vector3(0f, -room.Height * 0.5f + 0.08f, 0.24f), new Vector2(room.Width - 0.02f, 0.16f));
                SyncUndergroundRoomArchitecture(root, room, corridors, shaft);
                // This marker describes corridor reachability only; operation has its own words below.
                UpdateOrCreateQuad(root, "Connection Status", room.IsReachable
                        ? new Color(0.48f, 0.72f, 0.82f) : new Color(1f, 0.42f, 0.34f),
                    new Vector3(room.Width * 0.5f - 0.18f, room.Height * 0.5f - 0.16f, 0.21f),
                    new Vector2(0.045f, 0.12f));
                UpdateUndergroundSign(root, "Connection Label", room.IsReachable ? "Connected" : "Disconnected",
                    room.Width, room.Height * 0.5f - 0.26f,
                    room.IsReachable ? new Color(0.66f, 0.83f, 0.90f) : new Color(1f, 0.58f, 0.46f), 0.021f);
                var labelTransform = root.Find("Room Label");
                if (labelTransform == null)
                {
                    labelTransform = new GameObject("Room Label").transform;
                    labelTransform.SetParent(root, false);
                }
                labelTransform.localPosition = new Vector3(-room.Width * 0.5f + 0.15f,
                    room.Height * 0.5f - 0.08f, 0.20f);
                labelTransform.localScale = UndergroundWorldProportionScale;
                var label = labelTransform.GetComponent<TextMesh>();
                if (label == null) label = labelTransform.gameObject.AddComponent<TextMesh>();
                if (label != null)
                {
                    label.text = UndergroundRoomDisplayName(room.Type);
                    label.anchor = TextAnchor.UpperLeft;
                    label.characterSize = 0.032f;
                    label.fontSize = 64;
                    label.color = new Color(0.90f, 0.96f, 0.89f);
                    FitUndergroundSign(label, (room.Width - 0.44f) * GridPlacementController.UndergroundCellWidth);
                }
                _undergroundRoomViews[room.Id] = root.gameObject;
            }
        }

        public static string UndergroundRoomDisplayName(UndergroundRoomType type)
        {
            var name = type.ToString();
            var readable = new System.Text.StringBuilder(name.Length + 4);
            for (var i = 0; i < name.Length; i++)
            {
                if (i > 0 && char.IsUpper(name[i])) readable.Append(' ');
                readable.Append(name[i]);
            }
            return readable.ToString();
        }

        /// <summary>Reachability is displayed separately; staffing never implies productive output.</summary>
        public static string UndergroundRoomOperationLabel(UndergroundRoomOperationProjection room)
        {
            var state = !room.IsReachable ? "No access"
                : room.IsDisrupted ? "Disrupted"
                : room.Staff == 0 && room.RequiredStaff > 0 ? "Unstaffed"
                : room.Staff < room.RequiredStaff ? "Needs staff"
                : room.Cause == "Operating" ? "Operating"
                : room.Cause != null && room.Cause.Contains("supplies") ? "Needs supplies"
                : room.Cause != null && room.Cause.Contains("intel") ? "Needs intel"
                : "Waiting";
            return $"{state} · {room.Staff}/{room.RequiredStaff}";
        }

        private static void UpdateUndergroundSign(Transform root, string objectName, string text,
            int width, float y, Color color, float characterSize)
        {
            var sign = root.Find(objectName);
            if (sign == null)
            {
                sign = new GameObject(objectName).transform;
                sign.SetParent(root, false);
            }
            sign.localPosition = new Vector3(-width * 0.5f + 0.15f, y, 0.19f);
            sign.localScale = UndergroundWorldProportionScale;
            var label = sign.GetComponent<TextMesh>();
            if (label == null) label = sign.gameObject.AddComponent<TextMesh>();
            label.text = text;
            label.anchor = TextAnchor.UpperLeft;
            label.fontSize = 64;
            label.characterSize = characterSize;
            label.color = color;
            FitUndergroundSign(label, (width - 0.30f) * GridPlacementController.UndergroundCellWidth);
        }

        private static Vector3 UndergroundWorldProportionScale => new Vector3(
            1f / GridPlacementController.UndergroundCellWidth, 1f / GridPlacementController.UndergroundCellHeight, 1f);

        private static void FitUndergroundSign(TextMesh label, float availableWidth)
        {
            var renderedWidth = label.GetComponent<Renderer>().localBounds.size.x;
            if (renderedWidth > availableWidth && renderedWidth > 0f)
                label.characterSize *= Mathf.Max(0.1f, availableWidth) / renderedWidth;
        }

        private static Color UndergroundRoomColor(UndergroundRoomType type)
        {
            var index = (int)type;
            return new Color(0.16f + (index % 3) * 0.05f,
                0.25f + (index % 4) * 0.025f,
                0.31f + (index % 5) * 0.018f);
        }

        private void SyncUndergroundRoomArchitecture(Transform root, UndergroundRoom room,
            HashSet<UndergroundCell> corridors, HashSet<UndergroundCell> shafts)
        {
            var type = room.Type;
            var width = room.Width;
            var height = room.Height;
            var halfWidth = width * 0.5f;
            var halfHeight = height * 0.5f;
            var concrete = new Color(0.39f, 0.42f, 0.42f);
            var steel = new Color(0.18f, 0.23f, 0.26f);
            UpdateOrCreateQuad(root, "Left Retaining Wall", concrete,
                new Vector3(-halfWidth + 0.07f, 0f, 0.23f), new Vector2(0.10f, height - 0.08f));
            UpdateOrCreateQuad(root, "Right Retaining Wall", concrete,
                new Vector3(halfWidth - 0.07f, 0f, 0.23f), new Vector2(0.10f, height - 0.08f));
            UpdateOrCreateQuad(root, "Steel Ceiling Beam", steel,
                new Vector3(0f, halfHeight - 0.30f, 0.23f), new Vector2(width - 0.20f, 0.065f));
            UpdateOrCreateQuad(root, "Work Light", new Color(0.92f, 0.75f, 0.41f),
                new Vector3(halfWidth - 0.42f, halfHeight - 0.53f, 0.22f), new Vector2(Mathf.Min(0.5f, width * 0.3f), 0.035f));

            var panels = new FacadeMeshBuilder();
            var panelTop = halfHeight - 0.45f;
            var panelBottom = -halfHeight + 0.19f;
            SyncUndercityTexturedWall(root, width - 0.26f, panelTop, panelBottom);
            var hasTexturedWall = root.Find("Textured Industrial Wall") != null;
            for (var panel = 0; panel < width; panel++)
            {
                var left = -halfWidth + panel + 0.13f;
                var right = -halfWidth + panel + 0.87f;
                // Transparent batches sort as whole meshes; opaque fallback fills would cover the textured wall.
                if (!hasTexturedWall)
                    panels.AddQuad(left, right, panelBottom, panelTop, 0.275f,
                        new Color(0.26f + panel % 2 * 0.015f, 0.29f, 0.30f));
                panels.AddQuad(left, right, panelBottom, panelBottom + 0.025f, 0.268f, steel);
                for (var bolt = 0; bolt < 2; bolt++)
                {
                    var bx = bolt == 0 ? left + 0.04f : right - 0.04f;
                    panels.AddQuad(bx, bx + 0.015f, panelTop - 0.07f, panelTop - 0.055f, 0.265f, concrete);
                }
            }
            // A shaded recess and descending warm wall wash give the fixture depth without a real light.
            var lightX = halfWidth - 0.42f;
            panels.AddQuad(lightX - 0.31f, lightX + 0.31f, halfHeight - 0.58f, halfHeight - 0.49f,
                0.24f, new Color(0.07f, 0.10f, 0.11f));
            ReplaceUndercityDetailMesh(root, "Concrete Wall Panels", panels);
            var lightWash = new FacadeMeshBuilder();
            AddUndercityLightWash(lightWash, lightX, halfHeight - 0.57f,
                Mathf.Max(panelBottom, halfHeight - 1.03f), 0.24f, 0.44f, 0.255f);
            ReplaceUndercityDetailMesh(root, "Recessed Light Wash", lightWash, _coneMaterial);
            SyncUndergroundRoomPortals(root, room, corridors, shafts);

            var hub = root.Find("Access Hub Equipment");
            if (type == UndergroundRoomType.AccessHub)
            {
                if (hub == null)
                {
                    hub = new GameObject("Access Hub Equipment").transform;
                    hub.SetParent(root, false);
                }
                var fittings = new FacadeMeshBuilder();
                var floor = -halfHeight + 0.18f;
                FitUndercityEquipment(hub, floor, -halfHeight + 0.16f);
                var cabinetTop = Mathf.Min(panelTop - 0.08f, floor + 0.90f);
                for (var cabinet = 0; cabinet < 2; cabinet++)
                {
                    var left = -halfWidth + 0.25f + cabinet * 0.32f;
                    fittings.AddQuad(left, left + 0.29f, floor, cabinetTop, 0.225f, steel);
                    fittings.AddQuad(left + 0.03f, left + 0.26f, floor + 0.04f, cabinetTop - 0.035f,
                        0.215f, new Color(0.37f, 0.41f, 0.40f));
                    fittings.AddQuad(left + 0.21f, left + 0.225f, cabinetTop - 0.23f, cabinetTop - 0.14f,
                        0.205f, new Color(0.65f, 0.67f, 0.61f));
                }
                var benchLeft = Mathf.Max(-0.15f, -halfWidth + 1f);
                var benchRight = halfWidth - 0.22f;
                fittings.AddQuad(benchLeft, benchRight, floor + 0.20f, floor + 0.26f, 0.21f,
                    new Color(0.52f, 0.40f, 0.26f));
                fittings.AddQuad(benchLeft + 0.05f, benchLeft + 0.09f, floor, floor + 0.20f, 0.215f, steel);
                fittings.AddQuad(benchRight - 0.09f, benchRight - 0.05f, floor, floor + 0.20f, 0.215f, steel);
                fittings.AddQuad(benchLeft, benchRight, floor + 0.40f, floor + 0.47f, 0.235f,
                    new Color(0.49f, 0.45f, 0.33f));
                ReplaceUndercityDetailMesh(hub, "Lockers and Bench", fittings);
            }
            else if (hub != null) RetireUndercityDetailGroup(hub);

            // Machinery is background dressing, below utility paths and behind the resident crew.
            var generator = root.Find("Generator Equipment");
            if (type != UndergroundRoomType.Generator)
            {
                if (generator != null) RetireUndercityDetailGroup(generator);
                return;
            }
            if (generator == null)
            {
                generator = new GameObject("Generator Equipment").transform;
                generator.SetParent(root, false);
            }
            var equipmentWidth = Mathf.Min(2.5f, width - 0.65f);
            var equipmentHeight = Mathf.Min(0.95f, height - 0.65f);
            FitUndercityEquipment(generator, -halfHeight + 0.165f, -halfHeight + 0.16f);
            var centerY = -halfHeight + 0.20f + equipmentHeight * 0.5f;
            UpdateOrCreateQuad(generator, "Machine Housing", steel,
                new Vector3(-0.10f, centerY, 0.245f), new Vector2(equipmentWidth, equipmentHeight));
            UpdateOrCreateQuad(generator, "Machine Plinth", concrete,
                new Vector3(-0.10f, -halfHeight + 0.20f, 0.215f), new Vector2(equipmentWidth + 0.12f, 0.07f));
            for (var vent = 0; vent < 3; vent++)
            {
                var oldVent = generator.Find($"Cooling Vent {vent}");
                if (oldVent != null) DestroyGenerated(oldVent.gameObject);
            }
            var machinery = new FacadeMeshBuilder();
            var machineLeft = -0.10f - equipmentWidth * 0.5f;
            var floorY = -halfHeight + 0.24f;
            var engineRight = machineLeft + equipmentWidth * 0.55f;
            var top = floorY + equipmentHeight;
            machinery.AddQuad(machineLeft + 0.06f, engineRight, floorY + 0.08f, top - 0.12f,
                0.225f, new Color(0.30f, 0.37f, 0.33f));
            machinery.AddQuad(machineLeft + 0.08f, engineRight - 0.03f, top - 0.12f, top - 0.07f,
                0.215f, new Color(0.50f, 0.54f, 0.45f));
            for (var cylinder = 0; cylinder < 4; cylinder++)
            {
                var cx = machineLeft + 0.12f + cylinder * equipmentWidth * 0.10f;
                machinery.AddQuad(cx, cx + equipmentWidth * 0.055f, floorY + 0.14f, top - 0.15f,
                    0.215f, new Color(0.18f, 0.24f, 0.22f));
            }
            // Alternator casing: inset ends, cooling fins and a steel coupling to the engine block.
            var alternatorLeft = engineRight + 0.06f;
            var alternatorRight = machineLeft + equipmentWidth * 0.84f;
            machinery.AddQuad(engineRight - 0.02f, alternatorLeft + 0.03f, centerY - 0.035f, centerY + 0.035f,
                0.21f, concrete);
            machinery.AddQuad(alternatorLeft, alternatorRight, floorY + 0.10f, top - 0.13f,
                0.22f, new Color(0.40f, 0.45f, 0.44f));
            for (var fin = 0; fin < 6; fin++)
            {
                var fx = alternatorLeft + (alternatorRight - alternatorLeft) * (fin + 0.5f) / 6f;
                machinery.AddQuad(fx, fx + 0.012f, floorY + 0.13f, top - 0.16f,
                    0.21f, steel);
            }
            var controlLeft = machineLeft + equipmentWidth * 0.87f;
            machinery.AddQuad(controlLeft, machineLeft + equipmentWidth - 0.03f, floorY + 0.05f, top,
                0.22f, new Color(0.46f, 0.49f, 0.46f));
            machinery.AddQuad(controlLeft + 0.025f, machineLeft + equipmentWidth - 0.05f,
                top - equipmentHeight * 0.30f, top - equipmentHeight * 0.12f, 0.205f,
                new Color(0.08f, 0.13f, 0.13f));
            machinery.AddQuad(machineLeft + equipmentWidth * 0.18f, machineLeft + equipmentWidth * 0.18f + 0.045f,
                top - 0.07f, Mathf.Min(panelTop - 0.07f, top + 0.25f), 0.215f, concrete);
            machinery.AddQuad(machineLeft + equipmentWidth * 0.18f, engineRight,
                Mathf.Min(panelTop - 0.10f, top + 0.20f), Mathf.Min(panelTop - 0.055f, top + 0.245f),
                0.215f, concrete);
            ReplaceUndercityDetailMesh(generator, "Engine Alternator and Control", machinery);
            UpdateOrCreateQuad(generator, "Power Hazard Plate", new Color(1f, 0.72f, 0.20f),
                new Vector3(equipmentWidth * 0.36f - 0.10f, centerY, 0.205f), new Vector2(0.10f, 0.13f));
        }

        private static void FitUndercityEquipment(Transform equipment, float authoredFloor, float roomFloor)
        {
            // Uniformly fit the original equipment silhouette to the narrower columns; storeys scale only the shell.
            var fit = GridPlacementController.UndergroundCellWidth;
            var verticalScale = fit / GridPlacementController.UndergroundCellHeight;
            equipment.localScale = new Vector3(fit / GridPlacementController.UndergroundCellWidth, verticalScale, 1f);
            equipment.localPosition = new Vector3(0f, roomFloor - authoredFloor * verticalScale, 0f);
        }

        private void SyncUndercityTexturedWall(Transform root, float width, float top, float bottom)
        {
            if (_undercityPanelSprite == null)
            {
                var source = Resources.Load<Sprite>("Rooms/backdrop_utility_industrial");
                if (source == null || source.texture.width < 512 || source.texture.height < 512) return;
                // Approved wall panel only: exclude the cyan utility stripe, hazards and floor artwork.
                _undercityPanelSprite = Sprite.Create(source.texture, new Rect(80f, 384f, 432f, 128f),
                    new Vector2(0.5f, 0.5f), 360f, 0, SpriteMeshType.FullRect);
                _undercityPanelSprite.name = "Undercity Cropped Industrial Wall";
            }
            var panel = new FacadeMeshBuilder();
            panel.AddQuad(-width * 0.5f, width * 0.5f, bottom, top, 0.268f, Color.white);
            var texture = _undercityPanelSprite.texture;
            var crop = _undercityPanelSprite.rect;
            panel.UVs[0] = new Vector2(crop.xMin / texture.width, crop.yMin / texture.height);
            panel.UVs[1] = new Vector2(crop.xMax / texture.width, crop.yMin / texture.height);
            panel.UVs[2] = new Vector2(crop.xMax / texture.width, crop.yMax / texture.height);
            panel.UVs[3] = new Vector2(crop.xMin / texture.width, crop.yMax / texture.height);
            ReplaceUndercityDetailMesh(root, "Textured Industrial Wall", panel);
            var renderer = root.Find("Textured Industrial Wall").GetComponent<MeshRenderer>();
            renderer.GetPropertyBlock(_colorBlock);
            _colorBlock.SetTexture("_BaseMap", texture);
            _colorBlock.SetTexture("_MainTex", Texture2D.whiteTexture);
            renderer.SetPropertyBlock(_colorBlock);
        }

        private static void AddUndercityLightWash(FacadeMeshBuilder builder, float x, float top, float bottom,
            float nearHalfWidth, float farHalfWidth, float z)
        {
            var start = builder.AddQuad(x - farHalfWidth, x + farHalfWidth, bottom, top, z, Color.clear);
            builder.Vertices[start + 2] = new Vector3(x + nearHalfWidth, top, z);
            builder.Vertices[start + 3] = new Vector3(x - nearHalfWidth, top, z);
            var light = new Color(0.95f, 0.78f, 0.46f, 0.25f);
            builder.Colors[start] = new Color(light.r, light.g, light.b, 0f);
            builder.Colors[start + 1] = new Color(light.r, light.g, light.b, 0f);
            builder.Colors[start + 2] = light;
            builder.Colors[start + 3] = light;
        }

        private void ReplaceUndercityDetailMesh(Transform parent, string name, FacadeMeshBuilder builder, Material material = null)
        {
            var previous = parent.Find(name);
            if (previous != null)
            {
                var oldMesh = previous.GetComponent<MeshFilter>().sharedMesh;
                if (_coneMeshes.Remove(oldMesh)) DestroyGeneratedMesh(ref oldMesh);
            }
            var mesh = builder.BuildMesh(name);
            _coneMeshes.Add(mesh);
            var view = EnsureChildWithMesh(parent, name, mesh, material ?? _worldMaterial);
            SetColor(view.GetComponent<MeshRenderer>(), Color.white);
        }

        private void RetireUndercityDetailGroup(Transform root)
        {
            // Only our owned meshes belong to the lifetime list; primitive shared quads must survive.
            foreach (var filter in root.GetComponentsInChildren<MeshFilter>(true))
            {
                var mesh = filter.sharedMesh;
                if (_coneMeshes.Remove(mesh)) DestroyGeneratedMesh(ref mesh);
            }
            DestroyGenerated(root.gameObject);
        }

        private void SyncUndergroundRoomPortals(Transform root, UndergroundRoom room,
            HashSet<UndergroundCell> corridors, HashSet<UndergroundCell> shafts)
        {
            var builder = new FacadeMeshBuilder();
            var halfWidth = room.Width * 0.5f;
            var halfHeight = room.Height * 0.5f;
            var trim = new Color(0.50f, 0.53f, 0.49f);
            var opening = new Color(0.04f, 0.07f, 0.08f);
            var hasLeft = false;
            var hasRight = false;
            for (var row = 0; row < room.Height; row++)
            {
                var depth = room.Depth + row;
                for (var side = 0; side < 2; side++)
                {
                    var cell = new UndergroundCell(side == 0 ? room.X - 1 : room.X + room.Width, depth);
                    if (!corridors.Contains(cell) && !shafts.Contains(cell)) continue;
                    if (side == 0) hasLeft = true; else hasRight = true;
                    var x = side == 0 ? -halfWidth : halfWidth;
                    var y = halfHeight - row - 0.5f;
                    builder.AddQuad(x - 0.07f, x + 0.07f, y - 0.36f, y + 0.32f, 0.20f, opening);
                    builder.AddQuad(x - 0.10f, x + 0.10f, y + 0.32f, y + 0.37f, 0.19f, trim);
                    builder.AddQuad(x - 0.10f, x + 0.10f, y - 0.39f, y - 0.34f, 0.19f, trim);
                }
            }
            // Keep the retaining wall visible above connected side openings, rather than sealing them.
            root.Find("Left Retaining Wall").gameObject.SetActive(!hasLeft);
            root.Find("Right Retaining Wall").gameObject.SetActive(!hasRight);
            for (var column = 0; column < room.Width; column++)
            {
                for (var vertical = 0; vertical < 2; vertical++)
                {
                    var cell = new UndergroundCell(room.X + column,
                        vertical == 0 ? room.Depth - 1 : room.Depth + room.Height);
                    if (!corridors.Contains(cell) && !shafts.Contains(cell)) continue;
                    var x = -halfWidth + column + 0.5f;
                    var y = vertical == 0 ? halfHeight : -halfHeight;
                    // A hatch at the exact adjoining cell; a short ladder ties the landing to the room floor.
                    builder.AddQuad(x - 0.28f, x + 0.28f, y - 0.045f, y + 0.045f, 0.19f, opening);
                    builder.AddQuad(x - 0.30f, x - 0.26f, y - 0.12f, y + 0.12f, 0.18f, trim);
                    builder.AddQuad(x + 0.26f, x + 0.30f, y - 0.12f, y + 0.12f, 0.18f, trim);
                    for (var rung = 0; rung < 3; rung++)
                    {
                        var ry = vertical == 0 ? y - 0.15f - rung * 0.09f : y + 0.03f + rung * 0.09f;
                        builder.AddQuad(x - 0.20f, x + 0.20f, ry, ry + 0.025f, 0.18f, trim);
                    }
                }
            }
            ReplaceUndercityDetailMesh(root, "Connected Portals and Hatches", builder);
        }

        /// <summary>Bind a bounded visible crew to stable assigned resident IDs.</summary>
        public void SyncUndergroundCrew(UndergroundOperationsProjection operations)
        {
            if (_groundRoot == null) return;
            const int maxVisibleCrew = 24;
            var visibleIds = new HashSet<int>();
            var visibleCount = 0;
            if (operations != null)
            {
                for (var i = 0; i < operations.Rooms.Count; i++)
                {
                    var room = operations.Rooms[i];
                    if (!_undergroundRoomViews.TryGetValue(room.Id, out var roomView) || roomView == null) continue;
                    var root = roomView.transform;
                    var operating = room.IsReachable && !room.IsDisrupted && room.Cause == "Operating";
                    UpdateUndergroundSign(root, "Staff Status", UndergroundRoomOperationLabel(room),
                        room.Width, room.Height * 0.5f - 0.43f,
                        room.IsDisrupted || !room.IsReachable ? new Color(1f, 0.58f, 0.46f)
                            : operating ? new Color(0.68f, 0.88f, 0.71f) : new Color(0.96f, 0.77f, 0.47f), 0.020f);

                    var shownHere = Mathf.Min(room.AssignedResidentIds.Count, 4, maxVisibleCrew - visibleCount);
                    for (var crew = 0; crew < shownHere; crew++)
                    {
                        var residentId = room.AssignedResidentIds[crew];
                        if (!visibleIds.Add(residentId)) continue;
                        if (!_undergroundCrewViews.TryGetValue(residentId, out var skeletal) || skeletal == null)
                        {
                            var go = new GameObject($"Underground Crew {residentId}");
                            skeletal = go.AddComponent<NpcSkeletalHierarchy>();
                            skeletal.Initialize(residentId);
                            skeletal.SetCaption(null);
                            _undergroundCrewViews[residentId] = skeletal;
                        }
                        var crewRoot = root.Find("Crew World Scale");
                        if (crewRoot == null)
                        {
                            crewRoot = new GameObject("Crew World Scale").transform;
                            crewRoot.SetParent(root, false);
                        }
                        // Pose evaluation writes resident local scale, so compensation belongs to its parent.
                        crewRoot.localScale = UndergroundWorldProportionScale;
                        skeletal.transform.SetParent(crewRoot, false);
                        var spacing = Mathf.Min(0.72f, (room.Width - 0.6f) / Mathf.Max(1, shownHere));
                        skeletal.transform.localPosition = new Vector3(
                            (crew - (shownHere - 1) * 0.5f) * spacing * GridPlacementController.UndergroundCellWidth,
                            (-room.Height * 0.5f + 0.21f) * GridPlacementController.UndergroundCellHeight, 0.12f);
                        skeletal.SetFacing(residentId % 2 == 0 ? 1f : -1f);
                        skeletal.SetAnimationClip(room.IsDisrupted ? NpcAnimationClip.QueueWait : NpcAnimationClip.Idle);
                        visibleCount++;
                    }
                }
            }
            var retired = new List<int>();
            foreach (var pair in _undergroundCrewViews)
                if (!visibleIds.Contains(pair.Key))
                {
                    if (pair.Value != null) DestroyGenerated(pair.Value.gameObject);
                    retired.Add(pair.Key);
                }
            for (var i = 0; i < retired.Count; i++) _undergroundCrewViews.Remove(retired[i]);
        }

        public void AnimateUndergroundCrew(float time)
        {
            foreach (var crew in _undergroundCrewViews.Values)
                if (crew != null) crew.ApplyProceduralAnimation(time);
        }

        private void RetireMissingCellViews(Dictionary<UndergroundCell, GameObject> views, HashSet<UndergroundCell> active)
        {
            var retired = new List<UndergroundCell>();
            foreach (var pair in views)
                if (!active.Contains(pair.Key))
                {
                    if (pair.Value != null) RetireUndercityDetailGroup(pair.Value.transform);
                    retired.Add(pair.Key);
                }
            for (var i = 0; i < retired.Count; i++) views.Remove(retired[i]);
        }

        private static void DestroyGenerated(GameObject view)
        {
            if (view == null) return;
            if (UnityEngine.Application.isPlaying) Object.Destroy(view);
            else Object.DestroyImmediate(view);
        }

        private void EnsureExteriorWindows(TowerTopologyProjection topology, int floorCount)
        {
            _windowLightingEntries.Clear();

            // Left Facade Windows & Light Cones
            for (var f = 0; f < floorCount; f++)
            {
                var slab = topology != null && topology.TryGetFloorSlab(f, out var s) ? s : new CellBounds(f, -14, 16);
                var worldLeft = -2.4f + slab.MinX * 0.5f;
                var floorY = TowerStructurePresenter.FloorY(f);
                var windowX = worldLeft - 0.16f;
                var centerY = floorY + 0.03f;

                // Window Frame Header (Z = -0.05m)
                var frameObj = UpdateOrCreateQuad(_leftFacadeRoot, $"Left Window Frame {f}", WindowFrameColor,
                    new Vector3(windowX, floorY + 0.46f, -0.05f),
                    new Vector2(0.24f, 0.08f));
                if (!_leftWindowFrames.Contains(frameObj)) _leftWindowFrames.Add(frameObj);

                // Window Sill (Z = -0.05m)
                var sillObj = UpdateOrCreateQuad(_leftFacadeRoot, $"Left Window Sill {f}", WindowSillColor,
                    new Vector3(windowX, floorY - 0.40f, -0.05f),
                    new Vector2(0.26f, 0.06f));
                if (!_leftWindowSills.Contains(sillObj)) _leftWindowSills.Add(sillObj);

                // Recessed Window Glass (Z = 0.00m) — uses shared _worldMaterial
                var glassObj = UpdateOrCreateQuad(_leftFacadeRoot, $"Left Window Glass {f}", WindowDayColor,
                    new Vector3(windowX, centerY, 0.00f),
                    new Vector2(0.20f, 0.78f));
                if (!_leftWindowGlasses.Contains(glassObj)) _leftWindowGlasses.Add(glassObj);

                // Volumetric Light Cone (Z = -0.20m, projects outward to the left, dir = -1)
                var coneObj = UpdateOrCreateLightCone(_volumetricLightRoot, $"Left Light Cone {f}",
                    new Vector3(windowX, centerY, 0f), 1.20f, -1f);
                if (!_volumetricCones.Contains(coneObj)) _volumetricCones.Add(coneObj);

                var glassRenderer = glassObj.GetComponent<MeshRenderer>();
                var coneRenderer = coneObj.GetComponent<MeshRenderer>();
                _windowLightingEntries.Add(new WindowLightingEntry(glassRenderer, coneRenderer, f, true));
            }

            // Right Facade Windows & Light Cones (Upper floors, f >= 1)
            for (var f = 1; f < floorCount; f++)
            {
                var slab = topology != null && topology.TryGetFloorSlab(f, out var s) ? s : new CellBounds(f, -14, 16);
                var worldRight = -2.4f + (slab.MaxX + 1) * 0.5f;
                var floorY = TowerStructurePresenter.FloorY(f);
                var windowX = worldRight + 0.16f;
                var centerY = floorY + 0.03f;

                // Window Frame Header (Z = -0.05m)
                var frameObj = UpdateOrCreateQuad(_rightFacadeRoot, $"Right Window Frame {f}", WindowFrameColor,
                    new Vector3(windowX, floorY + 0.46f, -0.05f),
                    new Vector2(0.24f, 0.08f));
                if (!_rightWindowFrames.Contains(frameObj)) _rightWindowFrames.Add(frameObj);

                // Window Sill (Z = -0.05m)
                var sillObj = UpdateOrCreateQuad(_rightFacadeRoot, $"Right Window Sill {f}", WindowSillColor,
                    new Vector3(windowX, floorY - 0.40f, -0.05f),
                    new Vector2(0.26f, 0.06f));
                if (!_rightWindowSills.Contains(sillObj)) _rightWindowSills.Add(sillObj);

                // Recessed Window Glass (Z = 0.00m) — uses shared _worldMaterial
                var glassObj = UpdateOrCreateQuad(_rightFacadeRoot, $"Right Window Glass {f}", WindowDayColor,
                    new Vector3(windowX, centerY, 0.00f),
                    new Vector2(0.20f, 0.78f));
                if (!_rightWindowGlasses.Contains(glassObj)) _rightWindowGlasses.Add(glassObj);

                // Volumetric Light Cone (Z = -0.20m, projects outward to the right, dir = +1)
                var coneObj = UpdateOrCreateLightCone(_volumetricLightRoot, $"Right Light Cone {f}",
                    new Vector3(windowX, centerY, 0f), 1.20f, 1f);
                if (!_volumetricCones.Contains(coneObj)) _volumetricCones.Add(coneObj);

                var glassRenderer = glassObj.GetComponent<MeshRenderer>();
                var coneRenderer = coneObj.GetComponent<MeshRenderer>();
                _windowLightingEntries.Add(new WindowLightingEntry(glassRenderer, coneRenderer, f, false));
            }

            RebuildConeBatch();
            UpdateWindowLighting(new DayPhase(1, 12, 0, false));
        }

        private void BuildRoofline(TowerTopologyProjection topology, int floorCount, CellBounds topSlab)
        {
            var topFloor = floorCount - 1;
            var worldLeft = -2.4f + topSlab.MinX * 0.5f;
            var worldRight = -2.4f + (topSlab.MaxX + 1) * 0.5f;
            var deckY = TowerStructurePresenter.FloorY(topFloor) + 1.01f; // top of slab ceiling

            var roofLeft = worldLeft - WallThickness - CorniceOverhang;
            var roofRight = worldRight + WallThickness + CorniceOverhang;
            var roofWidth = roofRight - roofLeft;
            var roofCenter = (roofLeft + roofRight) * 0.5f;

            // 1. Structural Roof Slab
            UpdateOrCreateQuad(_rooflineRoot, "Roof Structural Slab", RoofDeckColor,
                new Vector3(roofCenter, deckY + RoofDeckThickness * 0.5f, 0.15f),
                new Vector2(roofWidth, RoofDeckThickness));

            // 2. Cornice Overhang Fascia Lip
            UpdateOrCreateQuad(_rooflineRoot, "Cornice Overhang Fascia", CorniceTrimColor,
                new Vector3(roofCenter, deckY + 0.04f, 0.12f),
                new Vector2(roofWidth + 0.08f, 0.08f));

            // 3. Roof Ballast & Gravel Deck
            var deckTopY = deckY + RoofDeckThickness;
            UpdateOrCreateQuad(_rooflineRoot, "Roof Gravel Ballast", RoofBallastColor,
                new Vector3(roofCenter, deckTopY + 0.03f, 0.16f),
                new Vector2(Mathf.Max(0.5f, roofWidth - 0.60f), 0.06f));

            // 4. Parapet Walls
            var leftParapetX = worldLeft - WallThickness + 0.06f;
            var rightParapetX = worldRight + WallThickness - 0.06f;

            UpdateOrCreateQuad(_rooflineRoot, "Left Parapet Wall", WallCoreColor,
                new Vector3(leftParapetX, deckTopY + ParapetHeight * 0.5f, 0.10f),
                new Vector2(0.24f, ParapetHeight));
            UpdateOrCreateQuad(_rooflineRoot, "Left Parapet Coping", CorniceTrimColor,
                new Vector3(leftParapetX, deckTopY + ParapetHeight + 0.04f, 0.08f),
                new Vector2(0.30f, 0.08f));

            UpdateOrCreateQuad(_rooflineRoot, "Right Parapet Wall", WallCoreColor,
                new Vector3(rightParapetX, deckTopY + ParapetHeight * 0.5f, 0.10f),
                new Vector2(0.24f, ParapetHeight));
            UpdateOrCreateQuad(_rooflineRoot, "Right Parapet Coping", CorniceTrimColor,
                new Vector3(rightParapetX, deckTopY + ParapetHeight + 0.04f, 0.08f),
                new Vector2(0.30f, 0.08f));

            // 5. Rooftop Mechanical Fixtures
            BuildRooftopFixtures(deckTopY, roofLeft, roofRight);
        }

        private void BuildRooftopFixtures(float deckTopY, float roofLeft, float roofRight)
        {
            // Elevator Penthouse Machinery Housing (-1.90m shaft center)
            const float shaftX = -1.90f;
            UpdateOrCreateQuad(_fixturesRoot, "Elevator Penthouse Housing", FixtureMetalColor,
                new Vector3(shaftX, deckTopY + 0.45f, 0.12f),
                new Vector2(1.24f, 0.90f));
            UpdateOrCreateQuad(_fixturesRoot, "Elevator Penthouse Cap", CorniceTrimColor,
                new Vector3(shaftX, deckTopY + 0.94f, 0.10f),
                new Vector2(1.36f, 0.08f));
            UpdateOrCreateQuad(_fixturesRoot, "Elevator Penthouse Louver", RoofBallastColor,
                new Vector3(shaftX + 0.28f, deckTopY + 0.50f, 0.08f),
                new Vector2(0.42f, 0.32f));

            // Rooftop HVAC Chiller Unit
            var hvacX = shaftX + 2.4f;
            if (hvacX < roofRight - 1.2f)
            {
                UpdateOrCreateQuad(_fixturesRoot, "Rooftop HVAC Chiller", FixtureMetalColor,
                    new Vector3(hvacX, deckTopY + 0.28f, 0.14f),
                    new Vector2(0.85f, 0.56f));
                UpdateOrCreateQuad(_fixturesRoot, "HVAC Fan Cowling L", RoofBallastColor,
                    new Vector3(hvacX - 0.20f, deckTopY + 0.59f, 0.11f),
                    new Vector2(0.28f, 0.08f));
                UpdateOrCreateQuad(_fixturesRoot, "HVAC Fan Cowling R", RoofBallastColor,
                    new Vector3(hvacX + 0.20f, deckTopY + 0.59f, 0.11f),
                    new Vector2(0.28f, 0.08f));
            }

            // Communications Mast & Aviation Warning Light
            var mastX = roofLeft + 1.20f;
            UpdateOrCreateQuad(_fixturesRoot, "Communications Mast", DownspoutColor,
                new Vector3(mastX, deckTopY + 1.20f, 0.14f),
                new Vector2(0.06f, 2.40f));
            UpdateOrCreateQuad(_fixturesRoot, "Mast Cross Arm", DownspoutColor,
                new Vector3(mastX, deckTopY + 1.80f, 0.13f),
                new Vector2(0.40f, 0.04f));
            UpdateOrCreateQuad(_fixturesRoot, "Aviation Warning Beacon", BeaconGlowColor,
                new Vector3(mastX, deckTopY + 2.44f, -0.45f),
                new Vector2(0.12f, 0.12f));

            // Roof Access Hatch
            var hatchX = shaftX - 1.8f;
            if (hatchX > roofLeft + 0.8f)
            {
                UpdateOrCreateQuad(_fixturesRoot, "Roof Access Hatch", FixtureMetalColor,
                    new Vector3(hatchX, deckTopY + 0.22f, 0.14f),
                    new Vector2(0.55f, 0.44f));
            }
        }

        private void BuildSetbackTerraces(TowerTopologyProjection topology, int floorCount)
        {
            if (topology == null || floorCount <= 1) return;

            for (var f = 0; f < floorCount - 1; f++)
            {
                if (!topology.TryGetFloorSlab(f, out var lower) || !topology.TryGetFloorSlab(f + 1, out var upper)) continue;

                // Right-side Stepback
                if (lower.MaxX > upper.MaxX)
                {
                    var upperRight = -2.4f + (upper.MaxX + 1) * 0.5f;
                    var lowerRight = -2.4f + (lower.MaxX + 1) * 0.5f + WallThickness;
                    var terraceWidth = lowerRight - upperRight;
                    var terraceCenter = (upperRight + lowerRight) * 0.5f;
                    var terraceY = TowerStructurePresenter.FloorY(f + 1) - 0.74f;

                    UpdateOrCreateQuad(_terracesRoot, $"Terrace Slab R {f}", RoofDeckColor,
                        new Vector3(terraceCenter, terraceY + 0.08f, 0.15f),
                        new Vector2(terraceWidth, 0.16f));
                    UpdateOrCreateQuad(_terracesRoot, $"Terrace Railing R {f}", CorniceTrimColor,
                        new Vector3(terraceCenter, terraceY + 0.36f, 0.12f),
                        new Vector2(terraceWidth, 0.38f));
                }

                // Left-side Stepback
                if (lower.MinX < upper.MinX)
                {
                    var lowerLeft = -2.4f + lower.MinX * 0.5f - WallThickness;
                    var upperLeft = -2.4f + upper.MinX * 0.5f;
                    var terraceWidth = upperLeft - lowerLeft;
                    var terraceCenter = (lowerLeft + upperLeft) * 0.5f;
                    var terraceY = TowerStructurePresenter.FloorY(f + 1) - 0.74f;

                    UpdateOrCreateQuad(_terracesRoot, $"Terrace Slab L {f}", RoofDeckColor,
                        new Vector3(terraceCenter, terraceY + 0.08f, 0.15f),
                        new Vector2(terraceWidth, 0.16f));
                    UpdateOrCreateQuad(_terracesRoot, $"Terrace Railing L {f}", CorniceTrimColor,
                        new Vector3(terraceCenter, terraceY + 0.36f, 0.12f),
                        new Vector2(terraceWidth, 0.38f));
                }
            }
        }

        private void CalculateStageBounds(int floorCount, CellBounds ground, CellBounds top)
        {
            var groundLeft = -2.4f + ground.MinX * 0.5f - WallThickness;
            var groundRight = -2.4f + (ground.MaxX + 1) * 0.5f + WallThickness;
            var topFloorY = TowerStructurePresenter.FloorY(floorCount - 1) + 1.01f + RoofDeckThickness + ParapetHeight;
            var streetY = TowerStructurePresenter.FloorY(0) - 0.74f;

            var leftZone = new Bounds(
                new Vector3(groundLeft - 6.0f, (streetY + topFloorY) * 0.5f, 0f),
                new Vector3(12.0f, topFloorY - streetY + 10.0f, 10.0f));

            var rightZone = new Bounds(
                new Vector3(groundRight + 8.0f, (streetY + topFloorY) * 0.5f, 0f),
                new Vector3(16.0f, topFloorY - streetY + 10.0f, 10.0f));

            var rooftopZone = new Bounds(
                new Vector3((groundLeft + groundRight) * 0.5f, topFloorY + 4.0f, 0f),
                new Vector3(groundRight - groundLeft + 4.0f, 8.0f, 10.0f));

            var interiorEnclosure = new Bounds(
                new Vector3((groundLeft + groundRight) * 0.5f, (streetY + topFloorY) * 0.5f, 0.5f),
                new Vector3(groundRight - groundLeft, topFloorY - streetY, 2.0f));

            _stageBounds = new OutsideStageBounds(
                leftZone, rightZone, rooftopZone, interiorEnclosure,
                new Vector2(groundLeft, topFloorY), new Vector2(groundRight, topFloorY), topFloorY);
        }

        public void UpdateLighting(DayPhase phase, TowerProjection projection = null, UtilitiesOverlayProjection utilities = null)
        {
            UpdateAviationBeacons(phase);
            UpdateWindowLighting(phase, projection, utilities);
        }

        private void UpdateAviationBeacons(DayPhase phase)
        {
            if (_fixturesRoot == null) return;
            // Beacon light pulses at night and dims by day
            var hour = phase.Hour + phase.Minute / 60f;
            var night = hour < 6f ? 1f : hour >= 18f ? 1f : 0f;
            var beacon = _fixturesRoot.Find("Aviation Warning Beacon");
            if (beacon != null)
            {
                var renderer = beacon.GetComponent<MeshRenderer>();
                if (renderer != null)
                {
                    var pulse = 0.5f + 0.5f * Mathf.Sin(Time.time * 4f);
                    var alpha = Mathf.Lerp(0.2f, 1.0f, night * pulse);
                    var col = new Color(BeaconGlowColor.r, BeaconGlowColor.g, BeaconGlowColor.b, alpha);
                    SetColor(renderer, col);
                }
            }
        }

        public void UpdateWindowLighting(DayPhase phase, TowerProjection projection = null, UtilitiesOverlayProjection utilities = null)
        {
            _floorPower.Clear();
            if (utilities != null)
                for (var i = 0; i < utilities.Floors.Count; i++)
                {
                    var floor = utilities.Floors[i];
                    _floorPower[floor.Floor] = floor.PowerConnected ? Mathf.Clamp01(floor.Voltage) : 0f;
                }
            _occupiedRooms.Clear();
            if (projection?.Residents != null)
                for (var r = 0; r < projection.Residents.Count; r++)
                {
                    var resident = projection.Residents[r];
                    if (resident.Status == TransitResidentStatus.InRoom && resident.RoomId.HasValue)
                        _occupiedRooms.Add(resident.RoomId.Value);
                }
            var hour = phase.Hour + phase.Minute / 60f;
            // Smooth continuous night factor: 1.0 fully at night, 0.0 fully by day.
            // Dawn ramp: 5.5h (full night) → 6.5h (full day). Dusk ramp: 19.5h → 20.5h.
            float smoothNight;
            if (hour < 5.5f || hour >= 20.5f)
                smoothNight = 1f;
            else if (hour < 6.5f)
                smoothNight = 6.5f - hour;          // 1.0 at 5.5h → 0.0 at 6.5h
            else if (hour < 19.5f)
                smoothNight = 0f;
            else
                smoothNight = hour - 19.5f;         // 0.0 at 19.5h → 1.0 at 20.5h

            for (var i = 0; i < _windowLightingEntries.Count; i++)
            {
                var entry = _windowLightingEntries[i];
                var slab = _renderedSlabs.TryGetValue(entry.Floor, out var bounds) ? bounds : default;
                var edge = -2.4f + (entry.IsLeft ? slab.MinX : slab.MaxX + 1) * 0.5f;
                var isOccupied = projection == null
                    ? (entry.IsLeft ? ((entry.Floor * 7 + 3) % 5 != 0) : ((entry.Floor * 13 + 2) % 5 != 0))
                    : IsBayOccupied(entry.Floor, entry.IsLeft ? edge : edge - 0.5f,
                        entry.IsLeft ? edge + 0.5f : edge);

                if (entry.GlassRenderer != null)
                {
                    var targetNightGlass = Color.Lerp(WindowNightDarkColor, WindowNightLitColor, isOccupied ? PowerOnFloor(entry.Floor) : 0f);
                    var currentGlassColor = Color.Lerp(WindowDayColor, targetNightGlass, smoothNight);
                    SetColor(entry.GlassRenderer, currentGlassColor);
                    if (_batchedGlassColors != null && i * 4 + 3 < _batchedGlassColors.Length)
                        for (var vertex = 0; vertex < 4; vertex++) _batchedGlassColors[i * 4 + vertex] = currentGlassColor;
                }

                if (entry.ConeRenderer != null)
                {
                    var targetNightCone = Color.Lerp(ConeNightDarkColor, ConeNightLitColor, isOccupied ? PowerOnFloor(entry.Floor) : 0f);
                    var currentConeColor = Color.Lerp(ConeDayColor, targetNightCone, smoothNight);
                    currentConeColor.a *= Mathf.Clamp01(WindowLightStrength);
                    SetColor(entry.ConeRenderer, currentConeColor);
                    if (_batchedConeColors != null && i * 4 + 3 < _batchedConeColors.Length)
                    {
                        for (var vertex = 0; vertex < 4; vertex++)
                        {
                            var color = currentConeColor;
                            if (vertex == 1 || vertex == 2) color.a = 0f;
                            _batchedConeColors[i * 4 + vertex] = color;
                        }
                    }
                }
            }

            if (_batchedConeMesh != null) _batchedConeMesh.colors = _batchedConeColors;
            if (_batchedGlassMesh != null) _batchedGlassMesh.colors = _batchedGlassColors;

            // Front Facade Modular Fenestration (F5)
            if (_fenestrationMesh != null && _fenestrationColors != null && _frontFenestrationEntries.Count > 0)
            {
                for (var i = 0; i < _frontFenestrationEntries.Count; i++)
                {
                    var entry = _frontFenestrationEntries[i];
                    bool isOccupied;
                    if (projection != null)
                    {
                        isOccupied = IsBayOccupied(entry.Floor, entry.MinX, entry.MaxX);
                    }
                    else
                    {
                        isOccupied = ((entry.Floor * 7 + entry.BayIndex * 3 + 1) % 5 != 0);
                    }

                    var targetNight = Color.Lerp(WindowNightDarkColor, WindowNightLitColor, isOccupied ? PowerOnFloor(entry.Floor) : 0f);
                    var c = Color.Lerp(WindowDayColor, targetNight, smoothNight);

                    var vStart = entry.VertexStartIndex;
                    if (vStart + 3 < _fenestrationColors.Length)
                    {
                        _fenestrationColors[vStart + 0] = c;
                        _fenestrationColors[vStart + 1] = c;
                        _fenestrationColors[vStart + 2] = c;
                        _fenestrationColors[vStart + 3] = c;
                    }
                }
                _fenestrationMesh.colors = _fenestrationColors;
            }

            // Front Facade Vitrines (Elevator, Hallways, Storefronts)
            if (_vitrineMesh != null && _vitrineColors != null)
            {
                var elevatorColor = Color.Lerp(ElevatorVitrineDayColor, ElevatorVitrineNightColor, smoothNight);
                for (var i = 0; i < _elevatorVitrineColorCount && _elevatorVitrineColorStart + i < _vitrineColors.Length; i++)
                {
                    _vitrineColors[_elevatorVitrineColorStart + i] = elevatorColor;
                }

                var storefrontColor = Color.Lerp(StorefrontVitrineDayColor, StorefrontVitrineNightColor, smoothNight);
                for (var i = 0; i < _storefrontVitrineColorCount && _storefrontVitrineColorStart + i < _vitrineColors.Length; i++)
                {
                    _vitrineColors[_storefrontVitrineColorStart + i] = storefrontColor;
                }

                var hallwayColor = Color.Lerp(HallwayVitrineDayColor, HallwayVitrineNightColor, smoothNight);
                for (var i = 0; i < _hallwayVitrineColorCount && _hallwayVitrineColorStart + i < _vitrineColors.Length; i++)
                {
                    _vitrineColors[_hallwayVitrineColorStart + i] = hallwayColor;
                }

                _vitrineMesh.colors = _vitrineColors;
            }
        }

        public void Clear()
        {
            if (_root != null)
            {
                if (UnityEngine.Application.isPlaying)
                {
                    _root.gameObject.SetActive(false);
                    _root.SetParent(null, false);
                    Object.Destroy(_root.gameObject);
                }
                else Object.DestroyImmediate(_root.gameObject);
            }

            for (var i = 0; i < _coneMeshes.Count; i++)
            {
                var m = _coneMeshes[i];
                if (m != null)
                {
                    if (UnityEngine.Application.isPlaying) Object.Destroy(m);
                    else Object.DestroyImmediate(m);
                }
            }
            _coneMeshes.Clear();
            if (_undercityPanelSprite != null)
            {
                if (UnityEngine.Application.isPlaying) Object.Destroy(_undercityPanelSprite);
                else Object.DestroyImmediate(_undercityPanelSprite);
                _undercityPanelSprite = null;
            }
            DestroyGeneratedMesh(ref _batchedConeMesh);
            _batchedConeColors = null;
            DestroyGeneratedMesh(ref _batchedGlassMesh);
            _batchedGlassColors = null;

            DestroyGeneratedMesh(ref _framingMesh);
            DestroyGeneratedMesh(ref _fenestrationMesh);
            DestroyGeneratedMesh(ref _vitrineMesh);
            _frontFenestrationEntries.Clear();
            _fenestrationColors = null;
            _vitrineColors = null;
            _framingObject = null;
            _fenestrationObject = null;
            _vitrinesObject = null;

            _root = null;
            _leftFacadeRoot = null;
            _rightFacadeRoot = null;
            _frontFacadeRoot = null;
            _rooflineRoot = null;
            _fixturesRoot = null;
            _terracesRoot = null;
            _volumetricLightRoot = null;
            _groundRoot = null;
            _undercityRoot = null;
            _excavationViews.Clear();
            _lairFloorViews.Clear();
            _corridorViews.Clear();
            _shaftViews.Clear();
            _undergroundRoomViews.Clear();
            _undergroundCrewViews.Clear();
            _accessCoreView = null;
            _renderedUndergroundRevision = -1;

            _leftWallSlices.Clear();
            _rightWallSlices.Clear();
            _leftSpandrels.Clear();
            _rightSpandrels.Clear();
            _leftWindowFrames.Clear();
            _leftWindowGlasses.Clear();
            _leftWindowSills.Clear();
            _rightWindowFrames.Clear();
            _rightWindowGlasses.Clear();
            _rightWindowSills.Clear();
            _volumetricCones.Clear();
            _windowLightingEntries.Clear();
            _terraceObjects.Clear();
            _roofObjects.Clear();
            _renderedFloorCount = -1;
            _renderedSlabs.Clear();
            _lightingTopology = null;
            _occupiedRooms.Clear();
        }

        public void Dispose()
        {
            Clear();
            if (_coneMaterial != null)
            {
                if (UnityEngine.Application.isPlaying) Object.Destroy(_coneMaterial);
                else Object.DestroyImmediate(_coneMaterial);
                _coneMaterial = null;
            }
            if (_glazingMaterial != null)
            {
                if (UnityEngine.Application.isPlaying) Object.Destroy(_glazingMaterial);
                else Object.DestroyImmediate(_glazingMaterial);
                _glazingMaterial = null;
            }
        }

        private GameObject UpdateOrCreateQuad(Transform parent, string name, Color color, Vector3 pos, Vector2 size, Material mat = null)
        {
            var child = parent.Find(name);
            GameObject go;
            MeshRenderer renderer;
            var targetMat = mat ?? _worldMaterial;
            if (child == null)
            {
                go = GameObject.CreatePrimitive(PrimitiveType.Quad);
                go.name = name;
                go.transform.SetParent(parent, false);
                var col = go.GetComponent<Collider>();
                if (col != null)
                {
                    if (UnityEngine.Application.isPlaying) Object.Destroy(col);
                    else Object.DestroyImmediate(col);
                }
                renderer = go.GetComponent<MeshRenderer>();
                renderer.sharedMaterial = targetMat;
            }
            else
            {
                go = child.gameObject;
                renderer = go.GetComponent<MeshRenderer>();
                if (targetMat != null) renderer.sharedMaterial = targetMat;
            }

            go.transform.localPosition = pos;
            go.transform.localScale = new Vector3(size.x, size.y, 1f);
            SetColor(renderer, color);
            return go;
        }

        // Keep per-window geometry for topology inspection, but submit its light volumes once.
        private void RebuildConeBatch()
        {
            DestroyGeneratedMesh(ref _batchedConeMesh);
            DestroyGeneratedMesh(ref _batchedGlassMesh);
            var glassVertices = new Vector3[_windowLightingEntries.Count * 4];
            _batchedGlassColors = new Color[glassVertices.Length];
            var vertices = new Vector3[_windowLightingEntries.Count * 4];
            var triangles = new int[_windowLightingEntries.Count * 6];
            var glassTriangles = new int[triangles.Length];
            _batchedConeColors = new Color[vertices.Length];
            for (var i = 0; i < _windowLightingEntries.Count; i++)
            {
                var glass = _windowLightingEntries[i].GlassRenderer;
                var glassSource = glass.GetComponent<MeshFilter>().sharedMesh.vertices;
                for (var v = 0; v < 4; v++)
                    glassVertices[i * 4 + v] = _volumetricLightRoot.InverseTransformPoint(glass.transform.TransformPoint(glassSource[v]));
                var glassIndices = glass.GetComponent<MeshFilter>().sharedMesh.triangles;
                for (var t = 0; t < 6; t++) glassTriangles[i * 6 + t] = i * 4 + glassIndices[t];
                glass.enabled = false;
                var renderer = _windowLightingEntries[i].ConeRenderer;
                var source = renderer.GetComponent<MeshFilter>().sharedMesh.vertices;
                for (var v = 0; v < 4; v++)
                    vertices[i * 4 + v] = _volumetricLightRoot.InverseTransformPoint(renderer.transform.TransformPoint(source[v]));
                var offset = i * 4;
                var indices = new[] { offset, offset + 1, offset + 2, offset, offset + 2, offset + 3 };
                Array.Copy(indices, 0, triangles, i * 6, 6);
                renderer.enabled = false;
            }
            _batchedConeMesh = new Mesh { name = "Batched Facade Light Cones" };
            _batchedConeMesh.vertices = vertices;
            _batchedConeMesh.triangles = triangles;
            _batchedConeMesh.colors = _batchedConeColors;
            _batchedConeMesh.RecalculateBounds();
            var batch = EnsureChildWithMesh(_volumetricLightRoot, "Batched Light Cones", _batchedConeMesh, _coneMaterial);
            SetColor(batch.GetComponent<MeshRenderer>(), Color.white);
            _batchedGlassMesh = new Mesh { name = "Batched Facade Flank Glazing" };
            _batchedGlassMesh.vertices = glassVertices;
            _batchedGlassMesh.triangles = glassTriangles;
            _batchedGlassMesh.colors = _batchedGlassColors;
            _batchedGlassMesh.RecalculateBounds();
            var glazing = EnsureChildWithMesh(_volumetricLightRoot, "Batched Flank Window Glass", _batchedGlassMesh, _glazingMaterial);
            SetColor(glazing.GetComponent<MeshRenderer>(), Color.white);
        }

        private GameObject UpdateOrCreateLightCone(
            Transform parent, string name, Vector3 origin, float length, float direction)
        {
            if (parent == null) return null;
            var child = parent.Find(name);
            GameObject go;
            MeshFilter filter;
            MeshRenderer renderer;
            Mesh mesh;

            if (child == null)
            {
                go = new GameObject(name);
                go.transform.SetParent(parent, false);
                filter = go.AddComponent<MeshFilter>();
                renderer = go.AddComponent<MeshRenderer>();
                mesh = CreateLightConeMesh(origin, length, direction, name);
                filter.sharedMesh = mesh;
                _coneMeshes.Add(mesh);
            }
            else
            {
                go = child.gameObject;
                filter = go.GetComponent<MeshFilter>();
                if (filter == null) filter = go.AddComponent<MeshFilter>();
                renderer = go.GetComponent<MeshRenderer>();
                if (renderer == null) renderer = go.AddComponent<MeshRenderer>();

                mesh = filter.sharedMesh;
                if (mesh == null)
                {
                    mesh = CreateLightConeMesh(origin, length, direction, name);
                    filter.sharedMesh = mesh;
                    _coneMeshes.Add(mesh);
                }
                else
                {
                    UpdateLightConeMesh(mesh, origin, length, direction);
                }
            }

            go.transform.localPosition = new Vector3(0f, 0f, -0.20f);
            if (_coneMaterial != null) renderer.sharedMaterial = _coneMaterial;
            SetColor(renderer, ConeDayColor);

            return go;
        }

        private static Mesh CreateLightConeMesh(Vector3 origin, float length, float direction, string name)
        {
            var mesh = new Mesh { name = name };
            UpdateLightConeMesh(mesh, origin, length, direction);
            return mesh;
        }

        private static void UpdateLightConeMesh(Mesh mesh, Vector3 origin, float length, float direction)
        {
            var v0 = new Vector3(origin.x, origin.y + 0.35f, 0f);
            var v1 = new Vector3(origin.x + direction * length, origin.y + 0.60f, 0f);
            var v2 = new Vector3(origin.x + direction * length, origin.y - 0.70f, 0f);
            var v3 = new Vector3(origin.x, origin.y - 0.35f, 0f);

            mesh.vertices = new[] { v0, v1, v2, v3 };
            mesh.triangles = new[]
            {
                0, 1, 2,
                0, 2, 3,
                0, 2, 1,
                0, 3, 2
            };
            mesh.colors = new[]
            {
                new Color(1f, 1f, 1f, 1f),
                new Color(1f, 1f, 1f, 0f),
                new Color(1f, 1f, 1f, 0f),
                new Color(1f, 1f, 1f, 1f)
            };
            mesh.uv = new[]
            {
                new Vector2(0f, 1f),
                new Vector2(1f, 1f),
                new Vector2(1f, 0f),
                new Vector2(0f, 0f)
            };
            mesh.RecalculateBounds();
        }


        private void SetColor(MeshRenderer renderer, Color color)
        {
            if (renderer == null) return;
            var material = renderer.sharedMaterial == _coneMaterial ? _coneMaterial
                : (renderer.sharedMaterial == _glazingMaterial ? _glazingMaterial : _worldMaterial);
            if (material != null && renderer.sharedMaterial != material)
                renderer.sharedMaterial = material;
            if (_colorBlock == null) _colorBlock = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(_colorBlock);
            _colorBlock.SetColor("_BaseColor", color);
            _colorBlock.SetColor("_Color", color);
            renderer.SetPropertyBlock(_colorBlock);
        }

        public void SetFacadeEnvelopeAlpha(float alpha)
        {
            _facadeEnvelopeAlpha = Mathf.Clamp01(alpha);
            if (_frontFacadeRoot == null) return;

            if (_facadeEnvelopeAlpha <= 0.001f)
            {
                _frontFacadeRoot.gameObject.SetActive(false);
            }
            else
            {
                _frontFacadeRoot.gameObject.SetActive(true);
                ApplyFacadeEnvelopeAlpha();
            }
        }

        public float GetEffectiveVitrineAlpha(VitrineType type)
        {
            var baseAlpha = type == VitrineType.ScenicElevator ? 0.15f : (type == VitrineType.Storefront ? 0.14f : 0.16f);
            return _facadeEnvelopeAlpha * baseAlpha;
        }

        public Color GetFenestrationColor(int floor, int bayIndex = 0)
        {
            if (_fenestrationColors == null || _fenestrationColors.Length == 0) return Color.clear;
            for (var i = 0; i < _frontFenestrationEntries.Count; i++)
            {
                var entry = _frontFenestrationEntries[i];
                if (entry.Floor == floor && entry.BayIndex == bayIndex)
                {
                    if (entry.VertexStartIndex < _fenestrationColors.Length)
                        return _fenestrationColors[entry.VertexStartIndex];
                }
            }
            return Color.clear;
        }

        public Color GetVitrineColor(VitrineType type)
        {
            if (_vitrineColors == null || _vitrineColors.Length == 0) return Color.clear;
            switch (type)
            {
                case VitrineType.ScenicElevator:
                    return _elevatorVitrineColorStart < _vitrineColors.Length ? _vitrineColors[_elevatorVitrineColorStart] : Color.clear;
                case VitrineType.Storefront:
                    return _storefrontVitrineColorStart < _vitrineColors.Length ? _vitrineColors[_storefrontVitrineColorStart] : Color.clear;
                case VitrineType.HallwayRibbon:
                    return _hallwayVitrineColorStart < _vitrineColors.Length ? _vitrineColors[_hallwayVitrineColorStart] : Color.clear;
                default:
                    return Color.clear;
            }
        }

        private float PowerOnFloor(int floor) => _floorPower.TryGetValue(floor, out var voltage) ? voltage : 1f;

        private bool IsBayOccupied(int floor, float minX, float maxX)
        {
            if (_lightingTopology == null) return false;
            var rooms = _lightingTopology.GetRoomsOnFloor(floor);
            for (var i = 0; i < rooms.Count; i++)
            {
                var room = rooms[i];
                if (!_occupiedRooms.Contains(room.Id.Value)) continue;
                var left = -2.4f + room.Bounds.MinX * 0.5f;
                var right = -2.4f + (room.Bounds.MaxX + 1) * 0.5f;
                if (left < maxX && right > minX) return true;
            }
            return false;
        }

        private void BuildFrontFacadeEnvelope(TowerTopologyProjection topology, int floorCount)
        {
            if (_frontFacadeRoot == null) return;

            DestroyGeneratedMesh(ref _framingMesh);
            DestroyGeneratedMesh(ref _fenestrationMesh);
            DestroyGeneratedMesh(ref _vitrineMesh);
            _frontFenestrationEntries.Clear();

            var framingBuilder = new FacadeMeshBuilder();
            var fenestrationBuilder = new FacadeMeshBuilder();
            var vitrineBuilder = new FacadeMeshBuilder();

            // Depth standards
            const float opaqueZ = -0.36f;
            const float vitrineZ = -0.345f;

            // F2: Scenic Glass Elevator Vitrine
            // Spans x in [-2.40f, -1.40f] across all 30 floors
            const float elevatorLeft = -2.40f;
            const float elevatorRight = -1.40f;
            var bottomY = TowerStructurePresenter.FloorY(0) - 0.74f;
            var topY = TowerStructurePresenter.FloorY(floorCount - 1) + 1.01f;

            _elevatorVitrineColorStart = vitrineBuilder.AddQuad(
                elevatorLeft, elevatorRight, bottomY, topY, vitrineZ, ElevatorVitrineDayColor);
            _elevatorVitrineColorCount = 4;

            // F4: Ground-Level Storefront Vitrines
            // Floor 0 retail, diner, concourse: x in [-8.4f, 4.6f], height = 1.15m, alpha = 0.14
            var groundY = TowerStructurePresenter.FloorY(0);
            var storefrontMinY = groundY - 0.62f;
            var storefrontMaxY = storefrontMinY + 1.15f;
            var groundSlab = topology != null && topology.TryGetFloorSlab(0, out var ground)
                ? ground : new CellBounds(0, -14, 16);
            var storefrontLeft = -2.4f + groundSlab.MinX * 0.5f;
            var storefrontRight = -2.4f + (groundSlab.MaxX + 1) * 0.5f;

            _storefrontVitrineColorStart = vitrineBuilder.AddQuad(
                storefrontLeft, storefrontRight, storefrontMinY, storefrontMaxY, vitrineZ, StorefrontVitrineDayColor);
            _storefrontVitrineColorCount = 4;

            _hallwayVitrineColorStart = vitrineBuilder.Vertices.Count;

            // Build floors:
            for (var f = 0; f < floorCount; f++)
            {
                var floorY = TowerStructurePresenter.FloorY(f);
                var slab = topology != null && topology.TryGetFloorSlab(f, out var s) ? s : new CellBounds(f, -14, 16);
                var worldLeft = -2.4f + slab.MinX * 0.5f;
                var worldRight = -2.4f + (slab.MaxX + 1) * 0.5f;

                // F1: Floor Spandrel Band across slab edge
                framingBuilder.AddQuad(worldLeft, worldRight, floorY - 0.74f, floorY - 0.58f, opaqueZ, SpandrelColor);

                // F3: Circulation Hallway Glazing Ribbons at y in [floorY - 0.68f, floorY + 0.22f], alpha = 0.16
                var ribbonMinY = floorY - 0.68f;
                var ribbonMaxY = floorY + 0.22f;
                if (worldLeft < elevatorLeft)
                {
                    vitrineBuilder.AddQuad(worldLeft, Mathf.Min(worldRight, elevatorLeft), ribbonMinY, ribbonMaxY, vitrineZ, HallwayVitrineDayColor);
                }
                if (elevatorRight < worldRight)
                {
                    vitrineBuilder.AddQuad(Mathf.Max(worldLeft, elevatorRight), worldRight, ribbonMinY, ribbonMaxY, vitrineZ, HallwayVitrineDayColor);
                }

                // Horizontal Transoms (Curtain wall framing)
                framingBuilder.AddQuad(worldLeft, worldRight, floorY + 0.22f, floorY + 0.26f, opaqueZ, MullionColor);
                framingBuilder.AddQuad(worldLeft, worldRight, floorY + 0.81f, floorY + 0.85f, opaqueZ, MullionColor);

                // Vertical Mullions flanking elevator shaft
                framingBuilder.AddQuad(elevatorLeft - 0.04f, elevatorLeft, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);
                framingBuilder.AddQuad(elevatorRight, elevatorRight + 0.04f, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);

                // Flank edge vertical mullions
                framingBuilder.AddQuad(worldLeft, worldLeft + 0.06f, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);
                framingBuilder.AddQuad(worldRight - 0.06f, worldRight, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);

                // Modular Window Fenestration & Intermediate Mullions
                // Left Wing Bays
                var bayIndex = 0;
                var curX = worldLeft + 0.06f;
                var leftLimit = Mathf.Min(worldRight - 0.06f, elevatorLeft - 0.04f);
                while (curX + 0.40f <= leftLimit)
                {
                    var nextX = Mathf.Min(curX + 1.0f, leftLimit);
                    var windowMaxX = nextX - 0.04f;
                    if (windowMaxX > curX)
                    {
                        var vStart = fenestrationBuilder.AddQuad(
                            curX, windowMaxX, floorY + 0.26f, floorY + 0.81f, opaqueZ, WindowDayColor);
                        _frontFenestrationEntries.Add(new FrontFenestrationEntry(vStart, f, bayIndex, curX, windowMaxX));
                        bayIndex++;
                    }
                    if (nextX < leftLimit)
                    {
                        framingBuilder.AddQuad(nextX - 0.04f, nextX, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);
                    }
                    curX = nextX;
                }

                // Right Wing Bays
                curX = Mathf.Max(worldLeft + 0.06f, elevatorRight + 0.04f);
                var rightLimit = worldRight - 0.06f;
                while (curX + 0.40f <= rightLimit)
                {
                    var nextX = Mathf.Min(curX + 1.0f, rightLimit);
                    var windowMaxX = nextX - 0.04f;
                    if (windowMaxX > curX)
                    {
                        var vStart = fenestrationBuilder.AddQuad(
                            curX, windowMaxX, floorY + 0.26f, floorY + 0.81f, opaqueZ, WindowDayColor);
                        _frontFenestrationEntries.Add(new FrontFenestrationEntry(vStart, f, bayIndex, curX, windowMaxX));
                        bayIndex++;
                    }
                    if (nextX < rightLimit)
                    {
                        framingBuilder.AddQuad(nextX - 0.04f, nextX, floorY - 0.58f, floorY + 0.85f, opaqueZ, MullionColor);
                    }
                    curX = nextX;
                }
            }

            // Top floor parapet spandrel:
            var topSlab = topology != null && topology.TryGetFloorSlab(floorCount - 1, out var ts) ? ts : new CellBounds(floorCount - 1, -14, 16);
            var topWorldLeft = -2.4f + topSlab.MinX * 0.5f;
            var topWorldRight = -2.4f + (topSlab.MaxX + 1) * 0.5f;
            var topFloorY = TowerStructurePresenter.FloorY(floorCount - 1);
            framingBuilder.AddQuad(topWorldLeft, topWorldRight, topFloorY + 0.85f, topFloorY + 1.01f, opaqueZ, SpandrelColor);

            _hallwayVitrineColorCount = vitrineBuilder.Vertices.Count - _hallwayVitrineColorStart;

            // Generate combined meshes (3 draw calls total)
            _framingMesh = framingBuilder.BuildMesh("Curtain Wall Framing Mesh");
            _fenestrationMesh = fenestrationBuilder.BuildMesh("Modular Window Fenestration Mesh");
            _vitrineMesh = vitrineBuilder.BuildMesh("Transparent Vitrines Mesh");

            _fenestrationColors = _fenestrationMesh.colors;
            _vitrineColors = _vitrineMesh.colors;

            // Attach to GameObjects
            _framingObject = EnsureChildWithMesh(_frontFacadeRoot, "Curtain Wall Framing", _framingMesh, _worldMaterial);
            _fenestrationObject = EnsureChildWithMesh(_frontFacadeRoot, "Modular Window Fenestration", _fenestrationMesh, _glazingMaterial);
            _vitrinesObject = EnsureChildWithMesh(_frontFacadeRoot, "Transparent Vitrines (Light Cone)", _vitrineMesh, _glazingMaterial ?? _coneMaterial);

            // Hierarchy anchors
            var elevatorAnchor = EnsureChildTransform(_frontFacadeRoot, "Scenic Elevator Vitrine");
            elevatorAnchor.localPosition = new Vector3(-1.90f, (bottomY + topY) * 0.5f, vitrineZ);
            elevatorAnchor.localScale = new Vector3(1.0f, topY - bottomY, 1f);

            var hallwayAnchor = EnsureChildTransform(_frontFacadeRoot, "Circulation Hallway Vitrines");
            hallwayAnchor.localPosition = new Vector3(-1.90f, (bottomY + topY) * 0.5f, vitrineZ);

            var storefrontAnchor = EnsureChildTransform(_frontFacadeRoot, "Ground Storefront Vitrines");
            storefrontAnchor.localPosition = new Vector3((storefrontLeft + storefrontRight) * 0.5f, (storefrontMinY + storefrontMaxY) * 0.5f, vitrineZ);
            storefrontAnchor.localScale = new Vector3(storefrontRight - storefrontLeft, 1.15f, 1f);

            var spandrelAnchor = EnsureChildTransform(_frontFacadeRoot, "Spandrel Bands");
            spandrelAnchor.localPosition = new Vector3(-1.90f, (bottomY + topY) * 0.5f, opaqueZ);

            _frontFacadeRoot.gameObject.SetActive(_facadeEnvelopeAlpha > 0.001f);
            ApplyFacadeEnvelopeAlpha();
        }

        private void ApplyFacadeEnvelopeAlpha()
        {
            if (_frontFacadeRoot == null) return;

            if (_framingObject != null)
            {
                var r = _framingObject.GetComponent<MeshRenderer>();
                if (r != null)
                {
                    r.sharedMaterial = _facadeEnvelopeAlpha < 1f ? _glazingMaterial : _worldMaterial;
                    SetColorWithAlpha(r, Color.white, _facadeEnvelopeAlpha);
                }
            }

            if (_fenestrationObject != null)
            {
                var r = _fenestrationObject.GetComponent<MeshRenderer>();
                if (r != null) SetColorWithAlpha(r, Color.white, _facadeEnvelopeAlpha);
            }

            if (_vitrinesObject != null)
            {
                var r = _vitrinesObject.GetComponent<MeshRenderer>();
                if (r != null) SetColorWithAlpha(r, Color.white, _facadeEnvelopeAlpha);
            }
        }

        private void SetColorWithAlpha(MeshRenderer renderer, Color tint, float alpha)
        {
            if (renderer == null) return;
            if (_colorBlock == null) _colorBlock = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(_colorBlock);
            var col = new Color(tint.r, tint.g, tint.b, alpha);
            _colorBlock.SetColor("_BaseColor", col);
            _colorBlock.SetColor("_Color", col);
            renderer.SetPropertyBlock(_colorBlock);
        }

        private static GameObject EnsureChildWithMesh(Transform parent, string name, Mesh mesh, Material material)
        {
            var child = parent.Find(name);
            GameObject go;
            MeshFilter filter;
            MeshRenderer renderer;

            if (child == null)
            {
                go = new GameObject(name);
                go.transform.SetParent(parent, false);
                filter = go.AddComponent<MeshFilter>();
                renderer = go.AddComponent<MeshRenderer>();
            }
            else
            {
                go = child.gameObject;
                filter = go.GetComponent<MeshFilter>() ?? go.AddComponent<MeshFilter>();
                renderer = go.GetComponent<MeshRenderer>() ?? go.AddComponent<MeshRenderer>();
            }

            go.transform.localPosition = Vector3.zero;
            go.transform.localScale = Vector3.one;
            filter.sharedMesh = mesh;
            if (material != null) renderer.sharedMaterial = material;
            return go;
        }

        private static void DestroyGeneratedMesh(ref Mesh mesh)
        {
            if (mesh == null) return;
            if (UnityEngine.Application.isPlaying) Object.Destroy(mesh);
            else Object.DestroyImmediate(mesh);
            mesh = null;
        }

        private sealed class FacadeMeshBuilder
        {
            public readonly List<Vector3> Vertices = new List<Vector3>();
            public readonly List<int> Triangles = new List<int>();
            public readonly List<Color> Colors = new List<Color>();
            public readonly List<Vector2> UVs = new List<Vector2>();

            public int AddQuad(float minX, float maxX, float minY, float maxY, float z, Color color)
            {
                var startIndex = Vertices.Count;
                var v0 = new Vector3(minX, minY, z);
                var v1 = new Vector3(maxX, minY, z);
                var v2 = new Vector3(maxX, maxY, z);
                var v3 = new Vector3(minX, maxY, z);

                Vertices.Add(v0);
                Vertices.Add(v1);
                Vertices.Add(v2);
                Vertices.Add(v3);

                Colors.Add(color);
                Colors.Add(color);
                Colors.Add(color);
                Colors.Add(color);

                UVs.Add(new Vector2(0f, 0f));
                UVs.Add(new Vector2(1f, 0f));
                UVs.Add(new Vector2(1f, 1f));
                UVs.Add(new Vector2(0f, 1f));

                Triangles.Add(startIndex + 0);
                Triangles.Add(startIndex + 3);
                Triangles.Add(startIndex + 2);
                Triangles.Add(startIndex + 0);
                Triangles.Add(startIndex + 2);
                Triangles.Add(startIndex + 1);

                return startIndex;
            }

            public Mesh BuildMesh(string name)
            {
                var mesh = new Mesh { name = name };
                if (Vertices.Count > 65534)
                {
                    mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
                }
                mesh.SetVertices(Vertices);
                mesh.SetTriangles(Triangles, 0);
                mesh.SetColors(Colors);
                mesh.SetUVs(0, UVs);
                mesh.RecalculateNormals();
                mesh.RecalculateBounds();
                return mesh;
            }
        }
    }

    /// <summary>
    /// Immutable stage boundaries defining exterior atmospheric space and interior cutaway enclosure.
    /// </summary>
    public readonly struct OutsideStageBounds
    {
        public OutsideStageBounds(
            Bounds leftZone, Bounds rightZone, Bounds rooftopZone, Bounds interiorEnclosure,
            Vector2 leftScupper, Vector2 rightScupper, float roofDeckY)
        {
            LeftExteriorZone = leftZone;
            RightExteriorZone = rightZone;
            RooftopZone = rooftopZone;
            InteriorCutawayEnclosure = interiorEnclosure;
            LeftScupper = leftScupper;
            RightScupper = rightScupper;
            RoofDeckY = roofDeckY;
        }

        public Bounds LeftExteriorZone { get; }
        public Bounds RightExteriorZone { get; }
        public Bounds RooftopZone { get; }
        public Bounds InteriorCutawayEnclosure { get; }
        public Vector2 LeftScupper { get; }
        public Vector2 RightScupper { get; }
        public float RoofDeckY { get; }
    }
}
